def parse_nested_parens(*args):
    if len(args) != 1:
        return []
    arg = args[0]

    # If input is an empty string or empty list, return []
    if (isinstance(arg, str) and arg.strip() == '') or (isinstance(arg, list) and len(arg) == 0):
        return []

    # Convert input to list of groups of parentheses strings
    if isinstance(arg, str):
        groups = arg.split()
    else:
        groups = arg

    result = []
    for group in groups:
        max_depth = 0
        current_depth = 0
        for ch in group:
            if ch == '(':
                current_depth += 1
                if current_depth > max_depth:
                    max_depth = current_depth
            elif ch == ')':
                current_depth -= 1
        result.append(max_depth)

    return result

