def sum_to_n(*args):
    if len(args) == 1:
        arg = args[0]
        if isinstance(arg, int):
            n = arg
        elif isinstance(arg, list) and all(isinstance(x, int) for x in arg):
            if not arg:
                return 0
            n = max(arg)
        else:
            raise TypeError("Invalid argument type")
    else:
        raise TypeError("Invalid number of arguments")

    return n * (n + 1) // 2

