def fizz_buzz(*args):
    # Default divisors
    default_divisors = (11, 13)

    # Parse input according to the specification:
    # - fizz_buzz(n) --> one int argument
    # - fizz_buzz(n, divisors) --> int and tuple of two ints
    # - fizz_buzz(numbers) --> one list argument

    if len(args) == 1:
        arg = args[0]
        if isinstance(arg, int):
            # One int argument: consider range(0, n)
            n = arg
            divisors = default_divisors
            numbers = range(n if n > 0 else 0)
        elif isinstance(arg, list):
            # One list argument: consider numbers as given
            numbers = arg
            divisors = default_divisors
        else:
            # Unexpected single argument type, but spec does not require validation
            return 0
    elif len(args) == 2:
        n = args[0]
        divisors = args[1]
        # Expect n is int, divisors is tuple of two ints
        # Consider range(0, n)
        numbers = range(n if n > 0 else 0)
    else:
        # No arguments or more than 2: spec does not require handling
        return 0

    d1, d2 = divisors

    # Filter numbers divisible by d1 or d2
    filtered = (num for num in numbers if (num % d1 == 0 or num % d2 == 0))

    # Count occurrences of digit '7' in qualifying numbers
    count_7 = 0
    for num in filtered:
        count_7 += str(num).count('7')

    return count_7

