def anti_shuffle(*args):
    # Accept exactly one argument
    data = args[0]

    if isinstance(data, str):
        # Process string input:
        # Need to preserve all spaces exactly as in original string,
        # only sort characters inside each contiguous non-space piece.

        result = []
        i = 0
        n = len(data)

        while i < n:
            if data[i] == ' ':
                # Collect and append all consecutive spaces as is
                start = i
                while i < n and data[i] == ' ':
                    i += 1
                result.append(data[start:i])
            else:
                # Collect a contiguous non-space piece
                start = i
                while i < n and data[i] != ' ':
                    i += 1
                piece = data[start:i]
                # Sort characters of piece by ASCII ascending
                sorted_piece = ''.join(sorted(piece))
                result.append(sorted_piece)

        return ''.join(result)

    elif isinstance(data, list):
        # Process list of strings:
        # Each element may be a piece or spaces; sort characters inside each element.
        # Spaces remain sorted as well (spaces have ASCII 32).
        # Spec does not say to treat spaces specially in list elements.
        return [''.join(sorted(piece)) for piece in data]

    else:
        # Spec does not require error handling for other types
        # Just return input as is (or could raise, but spec forbids)
        return data

