def count_upper(*args):
    vowels = {'A', 'E', 'I', 'O', 'U'}
    # Determine the sequence of characters to process
    if len(args) == 1:
        seq = args[0]
        # If it's a string or a list of single-character strings, use as is
        if isinstance(seq, str):
            chars = seq
        elif isinstance(seq, list) and all(isinstance(c, str) and len(c) == 1 for c in seq):
            chars = seq
        else:
            # Otherwise, convert to list of characters
            chars = list(str(seq))
    else:
        # Multiple arguments given, treat args as the sequence
        # Convert all elements to single characters strings if needed
        # If any element is string longer than 1, split it into chars
        chars = []
        for item in args:
            if isinstance(item, str):
                if len(item) == 1:
                    chars.append(item)
                else:
                    chars.extend(item)
            else:
                # Convert non-string item to string then iterate chars
                chars.extend(str(item))

    count = 0
    for i in range(0, len(chars), 2):
        if chars[i] in vowels:
            count += 1
    return count

