def move_one_ball(arr):
    if not arr:
        return True

    n = len(arr)
    # Because arr has distinct elements, a "rotation" corresponds to choosing a pivot index:
    # rotating so that arr[pivot:] + arr[:pivot] is checked for sortedness.

    # Instead of actually rotating and checking each rotation,
    # we can leverage the fact that a rotated sorted array has at most one place where arr[i] > arr[i+1].

    # Count the number of "drops" in the original array
    drops = 0
    for i in range(n):
        if arr[i] > arr[(i + 1) % n]:
            drops += 1
            if drops > 1:
                return False

    return True

