def select_words(*args):
    # Parse arguments to get s (str) and n (int)
    if len(args) == 1:
        # Expecting a single tuple (s, n)
        s, n = args[0]
    elif len(args) == 2:
        # Two arguments, one str, one int, either order
        if isinstance(args[0], str) and isinstance(args[1], int):
            s, n = args[0], args[1]
        elif isinstance(args[0], int) and isinstance(args[1], str):
            s, n = args[1], args[0]
        else:
            # If types do not match expected, just assign by position
            s, n = args[0], args[1]
    else:
        # If no or more than 2 arguments, return empty list as no valid input
        return []

    if not s or s.strip() == '':
        return []

    vowels = set('aeiouAEIOU')
    words = s.split()

    result = []
    for word in words:
        non_vowels_count = sum(1 for c in word if c.isalpha() and c not in vowels)
        if non_vowels_count == n:
            result.append(word)

    return result

