def order_by_points(numbers):
    def digit_sum(n):
        s = str(n)
        if s[0] == '-':
            # first digit negative, rest positive
            return -int(s[1]) + sum(int(d) for d in s[2:])
        else:
            return sum(int(d) for d in s)

    # Sort by digit sum, stable sort preserves original order on ties
    return sorted(numbers, key=digit_sum)

