def parse_nested_parens(*args):
    # Determine the input form and produce a list of groups (strings)
    if len(args) == 0:
        groups = []
    elif len(args) == 1:
        arg = args[0]
        if isinstance(arg, str):
            groups = arg.split()
        elif isinstance(arg, list):
            groups = arg
        else:
            groups = []
    else:
        # More than one argument: not specified, treat as empty
        groups = []

    result = []
    for group in groups:
        if not group:
            continue  # ignore empty groups

        # Validate and compute max nesting depth
        depth = 0
        max_depth = 0
        valid = True
        for ch in group:
            if ch == '(':
                depth += 1
                if depth > max_depth:
                    max_depth = depth
            elif ch == ')':
                depth -= 1
                if depth < 0:
                    valid = False
                    break
            else:
                # Invalid character - according to spec groups only have parentheses,
                # but ignoring invalid chars not specified; treat as invalid group.
                valid = False
                break
        if valid and depth == 0:
            result.append(max_depth)
        # else ignore invalid or unbalanced groups

    return result

