def sort_even(items):
    if not items:
        # Return empty collection of same type
        return type(items)()

    # Extract elements at even indices
    even_elements = [items[i] for i in range(0, len(items), 2)]
    even_elements.sort()

    # Rebuild collection, replacing even indices with sorted elements
    result = []
    even_idx = 0
    for i in range(len(items)):
        if i % 2 == 0:
            result.append(even_elements[even_idx])
            even_idx += 1
        else:
            result.append(items[i])

    # Return same type as input
    if isinstance(items, tuple):
        return tuple(result)
    else:
        return result

