def triples_sum_to_zero(items):
    items = list(items)  # ensure we have indexable collection
    n = len(items)
    if n < 3:
        return False

    # Sort items along with their original indices to enable two-pointer approach
    indexed_items = sorted(enumerate(items), key=lambda x: x[1])

    for i in range(n - 2):
        idx_i, val_i = indexed_items[i]
        left = i + 1
        right = n - 1

        while left < right:
            idx_left, val_left = indexed_items[left]
            idx_right, val_right = indexed_items[right]
            total = val_i + val_left + val_right

            if total == 0:
                # Check distinct indices (positions) to satisfy distinct entries
                if len({idx_i, idx_left, idx_right}) == 3:
                    return True
                # If indices are not distinct (should not happen due to sorting by index distinctness)
                # Move pointers to find other candidates
                left += 1
                right -= 1
            elif total < 0:
                left += 1
            else:
                right -= 1
    return False

