def monotonic(seq):
    if len(seq) <= 1:
        return True

    nondecreasing = True
    nonincreasing = True

    for i in range(len(seq) - 1):
        if seq[i] < seq[i+1]:
            nonincreasing = False
        elif seq[i] > seq[i+1]:
            nondecreasing = False

        # Early exit if both are False
        if not nondecreasing and not nonincreasing:
            return False

    return nondecreasing or nonincreasing

