def move_one_ball(seq):
    if not seq:
        return True

    n = len(seq)

    def is_strictly_increasing(s):
        return all(s[i] < s[i+1] for i in range(len(s)-1))

    # Try all rightward cyclic moves: 0 to n-1
    # Rightward cyclic move by k means last k elements move to front
    for k in range(n):
        rotated = seq[-k:] + seq[:-k]
        if is_strictly_increasing(rotated):
            return True

    return False

