def select_words(*args):
    # Determine inputs based on args form
    if len(args) == 1 and isinstance(args[0], tuple) and len(args[0]) == 2:
        text, count = args[0]
    elif len(args) == 2:
        # Could be (str, int) or (int, str)
        if isinstance(args[0], str) and isinstance(args[1], int):
            text, count = args[0], args[1]
        elif isinstance(args[0], int) and isinstance(args[1], str):
            count, text = args[0], args[1]
        else:
            # Not specified to handle invalid inputs, so just fallback
            text, count = args[0], args[1]
    else:
        # Not specified what to do if no or more arguments
        # Assume empty input leading to empty list
        return []

    if not text:
        return []

    vowels = set('aeiouAEIOU')
    result = []
    for word in text.split():
        # Count consonants (including 'y' and 'Y')
        consonant_count = sum(1 for c in word if c.isalpha() and c.lower() not in vowels)
        if consonant_count == count:
            result.append(word)
    return result

