    # If args length != 1, or val not int or str, let it raise naturally
    val = args[0]
    if isinstance(val, str):
        # Convert to int
        val = int(val)
    elif not isinstance(val, int):
        # If not int or str, try to convert to int
        val = int(val)

    product = 1
    found_odd = False
    for ch in str(val):
        d = int(ch)
        if d % 2 == 1:
            product *= d
            found_odd = True

    return product if found_odd else 0

