def sort_even(l):
    # Extract elements at even indices
    even_elements = [l[i] for i in range(0, len(l), 2)]
    # Sort them ascendingly
    even_elements.sort()
    # Create a result list from input to preserve odd elements and overall length
    result = list(l)
    # Replace even index elements with sorted ones
    for idx, val in zip(range(0, len(l), 2), even_elements):
        result[idx] = val
    return result

