def triples_sum_to_zero(l: list):
    if len(l) < 3:
        return False

    l.sort()
    n = len(l)
    for i in range(n - 2):
        # To avoid duplicates, but not required by spec; no harm in leaving it out.
        # if i > 0 and l[i] == l[i-1]:
        #     continue

        left, right = i + 1, n - 1
        while left < right:
            s = l[i] + l[left] + l[right]
            if s == 0:
                return True
            elif s < 0:
                left += 1
            else:
                right -= 1
    return False

