def decode_shift(*args):
    # Determine the input string s from the arguments and convert if needed
    # Acceptable forms:
    # - decode_shift(s: str)
    # - decode_shift(s: str, shift: int)  (shift ignored, always 5 backward)
    # - decode_shift(s: list[str])
    # We only process the first argument as the string or list of strings.

    if not args:
        s = ""
    else:
        s = args[0]
        # if s is list[str], convert to string
        if isinstance(s, list):
            s = "".join(s)
        # if it's not string after that, convert to string forcibly (not required by spec)
        elif not isinstance(s, str):
            s = str(s)

    # Shift each character backward by 5 with wrap-around for lowercase letters
    result = []
    for ch in s:
