def monotonic(l: list) -> bool:
    if len(l) <= 1:
        return True

    nondecreasing = True
    nonincreasing = True

    for i in range(len(l) - 1):
        if l[i] > l[i + 1]:
            nondecreasing = False
        if l[i] < l[i + 1]:
            nonincreasing = False

        # Early exit if both are False
        if not nondecreasing and not nonincreasing:
            return False

    return nondecreasing or nonincreasing

