def compute_Last_Digit(*args):
    # Parse input to get a and b
    if len(args) == 1:
        # single argument, must be tuple or list of two integers
        arg = args[0]
        a, b = arg[0], arg[1]
    else:
        # two integer arguments
        a, b = args[0], args[1]

    if a == b:
        return 1  # empty product

    last_digit = 1
    for x in range(a + 1, b + 1):
        last_digit = (last_digit * (x % 10)) % 10

    return last_digit

