        # Then a = (x+y)/2, b = (x - y)/2 must be integers.
        # So x and y must have the same parity (both even or both odd)
        # To find if such x,y exist, check all factor pairs of n.

        # Special case: n == 0 is always True (0=0²-0²)
        if n == 0:
