        # For each divisor d, the pair is (d, n//d)
        # We consider both positive and negative factor pairs:
        # since n can be negative, factor pairs can be (d, n//d) or (-d, -n//d)
        # but checking only positive divisors and their complement is sufficient, 
        # considering sign in x,y since a,b integers can be negative.

        from math import isqrt

