            if abs_n % d == 0:
                x, y = d, n // d
                # Check parity of x,y
                if (x + y) % 2 == 0 and (x - y) % 2 == 0:
                    # a = (x + y)//2, b = (x - y)//2 are integers
                    return True
                # Also check the swapped pair (since factors multiply to n)
                # Actually swapping x and y corresponds to swapping a+b and a-b,
                # which is symmetric, so no need to check separately.

        return False

