    n = int(n)

    # Increment n to ensure we find palindrome strictly greater than n
    n += 1

    s = str(n)
    length = len(s)

    # Helper to create palindrome by mirroring left half to right
    def make_palindrome(left, odd_length):
        if odd_length:
            return left + left[:-1][::-1]
        else:
            return left + left[::-1]

    while True:
        s = str(n)
        length = len(s)
        half_len = (length + 1) // 2
        left = s[:half_len]

        # Construct palindrome from left half
        pal = make_palindrome(left, length % 2)

        if int(pal) >= n:
            return int(pal)
        else:
            # Need to increment the left half and try again
            # Convert left to int, add 1, then reconstruct palindrome
            left_int = int(left) + 1
            left_str = str(left_int)
            # If incrementing left changes its length (e.g. 99 -> 100), adjust length:
            if len(left_str) > len(left):
                # This means length of palindrome increases by 1 or 2
                # e.g. 999 -> next palindrome is 1001
                # So handle the case by constructing palindrome of length+1
                length += 1
                half_len = (length + 1) // 2
                left = '1' + ('0' * (half_len - 1))
                pal = make_palindrome(left, length % 2)
                return int(pal)
            else:
                left = left_str
                pal = make_palindrome(left, length % 2)
                if int(pal) >= n:
                    return int(pal)
                else:
                    # Increment again in next loop iteration
                    n = int(pal) + 1

