        # but if input doesn't match, no solution.
        return "No solution"

    # Special case: if n < 0, no non-negative solutions can exist
    # since a*x + b*y = n with x,y >= 0 and a,b integers,
    # if n < 0 and a,b >= 0, no solution,
    # but if a or b negative, we still must try.
    # So just proceed with search.

    # To avoid infinite loops, we determine a reasonable upper bound for x.
    # Since x,y >= 0, and a*x + b*y = n,
    # For non-negative a and b, x <= n//a (if a>0)
    # For negative coefficients, no trivial bound, but the problem does not specify.
    # We'll set an upper bound for searching x to avoid infinite loops.
    # Choose a large enough limit, for example up to max(0, n) + abs(b) + abs(a) + 1.
    # Or, more simply, search x from 0 up to n if n >= 0, else up to 0.
    # But if a or b negative, this might miss solutions.
    # Since spec does not say about negative coefficients,
    # to be safe, limit search to a reasonable number, e.g. 10^6.
    # This is a heuristic to prevent infinite loops.

    LIMIT = 10**6

    # If a == 0 and b == 0:
    if a == 0 and b == 0:
        # Equation reduces to 0 = n
        if n == 0:
            return (0, 0)
        else:
            return "No solution"

    # If a == 0:
    if a == 0:
        # Equation: b*y = n
        # y = n / b
        if b == 0:
            return "No solution"  # no solution if both zero handled above
        if (n % b == 0):
            y = n // b
            if y >= 0:
                return (0, y)
        return "No solution"

    # If b == 0:
    if b == 0:
        # Equation: a*x = n
        if (n % a == 0):
            x = n // a
            if x >= 0:
                return (x, 0)
        return "No solution"

    # General case: both a and b non-zero
    # Search x from 0 up to LIMIT
    for x in range(LIMIT+1):
        remainder = n - a*x
        # Check if remainder divisible by b
        if b == 0:
            # Already handled above, so skip
            continue
        if remainder % b == 0:
            y = remainder // b
            if y >= 0:
                return (x, y)

