def next_power_of_2(n: int | float) -> int:
    if n <= 0:
        return 1
    x = int(n)
    # If n is not an integer (e.g. 3.5), consider next power of two after ceil(n)
    if n > x:
        x += 1
    # Check if x is already a power of two
    # A number is a power of two if it has exactly one bit set in binary
    if x & (x - 1) == 0:
        return x
    # Otherwise, find the next power of two greater than x
    # Using bit_length: 
    # For x > 0, next power of two is 1 << x.bit_length()
    return 1 << x.bit_length()

