def even_binomial_Coeff_Sum(*args):
    # Helper function to compute the nth row of Pascal's triangle
    def pascal_row(n):
        row = [1]
        for k in range(1, n + 1):
            # Compute next element using the relation:
            # C(n,k) = C(n,k-1) * (n - k + 1) // k
            val = row[-1] * (n - k + 1) // k
            row.append(val)
        return row

