def find_Max(arr):
    if not arr:
        return None  # if empty, no max

    left, right = 0, len(arr) - 1

    # If array is not rotated (sorted in ascending order), the last element is max
    if arr[left] < arr[right]:
        return arr[right]

    while left < right:
        mid = (left + right) // 2

        # If mid element is greater than the right element, max is in the right half including mid
        if arr[mid] > arr[right]:
            left = mid + 1
        else:
            right = mid

    # After loop, left points to the smallest element.
    # Maximum element is just before left (consider wrap-around).
    return arr[left - 1] if left > 0 else arr[-1]

