def capital_words_spaces(*args):
    arg = args[0]
    if isinstance(arg, list):
        s = ''.join(arg)
    elif isinstance(arg, str):
        s = arg
    else:
        raise TypeError('Argument must be a string or list of strings')
    if s == '':
        return s
    if not any((c.isupper() for c in s[1:])):
        return s
    result = [s[0]]
    for c in s[1:]:
        if c.isupper():
            result.append(' ')
        result.append(c)
    return ''.join(result)

