def is_triangleexists(*args):
    tolerance = 1e-9

    # Determine the angles based on the input
    if len(args) == 1:
        # Single iterable argument
        angles = args[0]
        # Make sure it has exactly three elements
        if not (hasattr(angles, '__iter__') and len(angles) == 3):
            return False
    elif len(args) == 3:
        angles = args
    else:
        return False

    # Check each angle is a positive number greater than zero
    for angle in angles:
        if not (isinstance(angle, (int, float)) and angle > 0):
            return False

    # Check if the sum of the angles is 180 within the tolerance
    total = sum(angles)
    return abs(total - 180) <= tolerance

