def lcm(*args):
    # Parse inputs to get exactly two integers a and b
    if len(args) == 1:
        # Single argument, should be an iterable of exactly two integers
        pair = args[0]
        a, b = pair[0], pair[1]
    else:
        # Two separate integer arguments
        a, b = args[0], args[1]

    # If either input is zero, return 0
    if a == 0 or b == 0:
        return 0

    # Calculate gcd using Euclidean algorithm
    def gcd(x, y):
        while y:
            x, y = y, x % y
        return x

    a_abs, b_abs = abs(a), abs(b)
    return (a_abs // gcd(a_abs, b_abs)) * b_abs

