def compute_Last_Digit(*args):
    # Parse input arguments to get a, b
    if len(args) == 1 and isinstance(args[0], tuple):
        a, b = args[0]
    else:
        a, b = args

    # Compute the last digit of (b! / a!) = product of integers from (a+1) to b
    # To avoid large computations, we only track the last digit.
    # However, note that if any factor ends with 0, the product will end with 0.
    # So we can directly check for factors that are multiples of 10.
    # But since the product is (a+1)*(a+2)*...*b, if there's any factor multiple of 10, last digit is 0.

    # Check if there is any multiple of 10 in the range (a+1) to b
    for x in range(a + 1, b + 1):
        if x % 10 == 0:
            return 0

    # Otherwise, multiply last digits modulo 10
    last_digit = 1
    for x in range(a + 1, b + 1):
        last_digit = (last_digit * (x % 10)) % 10

    return last_digit

