def dif_Square(*args):
    # Helper to check if a and b are nonnegative integers with a > b and if value == a² - b²
    def check_pair(a, b, value=None):
        if not (isinstance(a, int) and isinstance(b, int)):
            return False
        if a <= b or b < 0:
            return False
        if value is not None:
            return (a * a - b * b) == value
        return True

    if len(args) == 1:
        arg = args[0]
        # If single argument is a tuple of two integers, treat as (a, b)
        if isinstance(arg, tuple) and len(arg) == 2:
            a, b = arg
            return check_pair(a, b)
        # Otherwise, single integer value case
        if not isinstance(arg, int):
            return False
        value = arg
        # value=0 cannot be expressed as a² - b² with a > b ≥ 0
        if value == 0:
            return False
        # We want to find any nonnegative integers a > b with a² - b² = value.

        # Using the identity: a² - b² = (a-b)(a+b) = value
        # Let x = a-b > 0, y = a+b > x (since a>b≥0)
        # Then value = x * y, with x < y, and (x+y) even (since a = (x+y)/2 and b=(y-x)/2 must be integers)
        # So iterate over divisors x of value, for x in 1..sqrt(value),
        # check if value % x == 0 and y = value//x > x, and (x + y) even.

        # For negative values, consider the same logic with absolute value
        # but since a,b ≥0 and a > b, a² - b² ≥ 0 always,
        # so negative values cannot be expressed. Return False.
        if value < 0:
            return False

        from math import isqrt

        limit = isqrt(value)
        for x in range(1, limit + 1):
            if value % x == 0:
                y = value // x
                if y > x and (x + y) % 2 == 0:
                    # a = (x + y) // 2
                    # b = (y - x) // 2
                    a = (x + y) // 2
                    b = (y - x) // 2
                    if b >= 0:
                        return True
        return False

    elif len(args) == 2:
        a, b = args
        if not (isinstance(a, int) and isinstance(b, int)):
            return False
        return check_pair(a, b, a * a - b * b)

    else:
        # Invalid number of arguments
        return False

