def next_smallest_palindrome(n: int) -> int:
    s = str(n)
    length = len(s)

    # Helper to check if all digits are '9'
    if all(ch == '9' for ch in s):
        # For all 9's, the next palindrome is 10..01 (length+1 digits)
        return int('1' + ('0' * (length - 1)) + '1')

    # Split into left, middle, right parts
    half = length // 2
    is_odd = (length % 2 != 0)

    if is_odd:
        left = s[:half]
        middle = s[half]
        right = s[half + 1:]
    else:
        left = s[:half]
        middle = ''
        right = s[half:]

    # Construct palindrome by mirroring left + middle
    if is_odd:
        palindrome = left + middle + left[::-1]
    else:
        palindrome = left + left[::-1]

    # If palindrome > n, return it
    if int(palindrome) > n:
        return int(palindrome)

    # Otherwise, increment the middle part and then mirror again
    if is_odd:
        # Increment the middle digit plus left as a whole number
        left_middle_num = int(left + middle)
        left_middle_num += 1
        left_middle_str = str(left_middle_num)

        # If length changed after increment (e.g. 99 -> 100)
        if len(left_middle_str) > len(left + middle):
            # This happens when middle and left overflow, so palindrome length increases by 1
            # For example, 999 -> 1001 handled above, but here means we just build palindrome from new left_middle_str
            # New palindrome length is length+1, so build palindrome accordingly
            new_left = left_middle_str[:-1]
            new_middle = left_middle_str[-1]
            palindrome = new_left + new_middle + new_left[::-1]
            return int(palindrome)
        else:
            new_left = left_middle_str[:-1]
            new_middle = left_middle_str[-1]
            palindrome = new_left + new_middle + new_left[::-1]
            return int(palindrome)
    else:
        # Even length: increment left as a number
        left_num = int(left)
        left_num += 1
        left_str = str(left_num)

        # If length changed after increment (e.g. 99 -> 100)
        if len(left_str) > len(left):
            # palindrome length increases by 1 (like 9999 -> 10001)
            palindrome = left_str + left_str[:-1][::-1]
            return int(palindrome)
        else:
            palindrome = left_str + left_str[::-1]
            return int(palindrome)

