def count(seq, correct_values=None):
    """
    Count how many values in the given sequence are considered correct according to a correctness condition.

    If correct_values is None, assume all values are correct.

    Parameters:
    - seq: iterable of values to check
    - correct_values: optional iterable of values considered correct (default None means all values are correct)

    Returns:
    - int: number of values in seq that are correct according to the condition
    """
    if correct_values is None:
        # All values considered correct
        return sum(1 for _ in seq)
    else:
        correct_set = set(correct_values)
        return sum(1 for x in seq if x in correct_set)

