def find_solution(*args):
    # Parse arguments
    if len(args) == 3:
        a, b, n = args
    elif len(args) == 2:
        (a, b), n = args
    else:
        # Not specified how to handle other cases, just return []
        return []

    # Handle the cases when a or b is zero
    if a == 0 and b == 0:
        # Equation is 0*x + 0*y = n
        # If n == 0, infinite solutions, but we return one: (0,0)
        # Else no solution
        return (0, 0) if n == 0 else []

    if a == 0:
        # Equation: b*y = n
        if b == 0:
            return (0, 0) if n == 0 else []
        if n % b == 0:
            return (0, n // b)
        else:
            return []

    if b == 0:
        # Equation: a*x = n
        if a == 0:
            return (0, 0) if n == 0 else []
        if n % a == 0:
            return (n // a, 0)
        else:
            return []

    # Now both a and b are non-zero.
    # Use Extended Euclidean Algorithm to find one particular solution to a*x + b*y = gcd(a,b)
    def extended_gcd(x, y):
        if y == 0:
            return (x, 1, 0)
        else:
            gcd, s, t = extended_gcd(y, x % y)
            return (gcd, t, s - (x // y) * t)

    gcd, x0, y0 = extended_gcd(abs(a), abs(b))

    # Check if n is divisible by gcd
    if n % gcd != 0:
        return []

    # Scale the solution to n
    factor = n // gcd
    x0 *= factor
    y0 *= factor

    # Adjust signs according to original a, b signs
    if a < 0:
        x0 = -x0
    if b < 0:
        y0 = -y0

    return (x0, y0)

