def next_power_of_2(x):
    # If x is a tuple (or any iterable), convert it to the first element recursively
    if isinstance(x, tuple):
        # According to the problem statement, the caller may pass a tuple[int, ...]
        # We treat the tuple as a numeric value by converting as follows:
        # For example, (5,) => 5, (5, 6) => 5 (only first element considered)
        # This matches "produce the same result for equivalent numeric values"
        if len(x) == 0:
            # empty tuple, treat as 0
            x = 0
        else:
            x = x[0]

    # Convert float inputs and others to float first, then to int if needed
    # The function must produce the same result for equivalent numeric values
    # So 5 and 5.0 produce the same result.
    try:
        val = float(x)
    except (TypeError, ValueError):
        # If conversion fails, treat as 0 (not specified, but to avoid crash)
        val = 0

    # For negative or zero inputs, return 1
    if val <= 0:
        return 1

    # For non-integers, we consider the smallest power of two >= val
    # Since powers of two are integers, we can work with int ceiling of val
    # For instance, next_power_of_2(5.1) -> 8
    n = int(val)
    if val > n:
        n += 1

    # Check if n is already a power of two
    # A number n is power of two if n & (n-1) == 0
    if n & (n - 1) == 0:
        return n

    # Otherwise find the next power of two greater than n
    # We can use bit_length to find the next power of two
    return 1 << (n.bit_length())

