    for i, ch in enumerate(s):
        expected0 = '0' if i % 2 == 0 else '1'
        expected1 = '1' if i % 2 == 0 else '0'
        if ch != expected0:
            flips_start0 += 1
        if ch != expected1:
            flips_start1 += 1

    return min(flips_start0, flips_start1)

