def highest_Power_of_2(*args):
    def single_highest_power_of_2(n):
        if n < 1:
            return 0
        # Find the largest power of two <= n using bit_length
        return 1 << (n.bit_length() - 1)

    # Flatten the input arguments to either a single int or a list of ints
    if len(args) == 0:
        # No arguments, treat as 0
        return 0
    elif len(args) == 1:
        arg = args[0]
        if isinstance(arg, int):
            return single_highest_power_of_2(arg)
        elif isinstance(arg, list):
            return [single_highest_power_of_2(x) for x in arg]
        else:
            # If single argument but not int or list, try to convert to int
            try:
                n = int(arg)
                return single_highest_power_of_2(n)
            except:
                # If cannot convert, treat as 0 as fallback
                return 0
    else:
        # Multiple arguments: treat as list of ints
        result = []
        for x in args:
            if isinstance(x, int):
                result.append(single_highest_power_of_2(x))
            elif isinstance(x, list):
                # Flatten lists inside args by extending results
                result.extend(single_highest_power_of_2(i) for i in x)
            else:
                try:
                    n = int(x)
                    result.append(single_highest_power_of_2(n))
                except:
                    result.append(0)
        return result

