def find_Max(seq: list[int] | tuple[int, ...]):
    if not seq:
        # Behavior unspecified for empty sequence; return None explicitly or let error occur
        return None

    low, high = 0, len(seq) - 1

    # If the sequence is not rotated (already sorted ascending)
    if seq[low] < seq[high]:
        return seq[high]

    while low < high:
        mid = (low + high) // 2
        # If mid element is greater than next element, mid is max
        if seq[mid] > seq[mid + 1]:
            return seq[mid]
        # If mid element is less than previous element, previous is max
        if seq[mid] < seq[mid - 1]:
            return seq[mid - 1]

        # Decide which half to choose
        if seq[mid] > seq[low]:
            # max must be in right half
            low = mid + 1
        else:
            # max is in left half
            high = mid - 1

    return seq[low]

