def sum_digits(*args):
    # Handle calls with one argument (int)
    if len(args) == 1:
        n = args[0]
        # If input is int, sum digits of abs(n)
        if isinstance(n, int):
            return sum(int(d) for d in str(abs(n)))
        # If input is list of ints, sum digits per int and then sum results
        if isinstance(n, list) and all(isinstance(x, int) for x in n):
            return sum(sum(int(d) for d in str(abs(x))) for x in n)
    # If called with two arguments: (int, int) - ignore second argument, sum digits of abs(n)
    if len(args) == 2:
        n = args[0]
        if isinstance(n, int) and isinstance(args[1], int):
            return sum(int(d) for d in str(abs(n)))

    # If input does not match above, fallback to 0 as safe default (spec does not require error handling)
    return 0

