def recur_gcd(*args):
    # Normalize input to two integers a and b
    if len(args) == 1:
        pair = args[0]
        a, b = pair[0], pair[1]
    else:
        a, b = args[0], args[1]

    def gcd(x, y):
        if y == 0:
            return abs(x)
        return gcd(y, x % y)

    g = gcd(a, b)
    l = abs(a * b) // g
    return (g, l)

