def text_match(text, sequence):
    # Normalize sequence to a list of strings (characters)
    if isinstance(sequence, str):
        seq = list(sequence)
    else:
        seq = list(sequence)

    if not seq:
        return ""

    n = len(text)
    m = len(seq)

    # Precompute for each position in text, the next occurrence of each character in seq
    # This will help quickly jump from one character to the next in the sequence
    # Build a dictionary of next occurrence arrays, one for each unique character in seq
    unique_chars = set(seq)
    next_pos = {c: [-1] * (n + 1) for c in unique_chars}

    # Initialize last seen positions as -1
    last_pos = {c: -1 for c in unique_chars}

    # Fill next_pos arrays from right to left
    for i in range(n - 1, -1, -1):
        c = text[i]
        for ch in unique_chars:
            next_pos[ch][i] = last_pos[ch]
        if c in unique_chars:
            last_pos[c] = i
            next_pos[c][i] = i
    # For position n (beyond end), next occurrences are -1
    for ch in unique_chars:
        next_pos[ch][n] = -1

    # Try each position in text as a possible start for the substring
    for start in range(n):
        if text[start] != seq[0]:
            # If first char of seq not here, try to jump to next occurrence of seq[0]
            start = next_pos[seq[0]][start]
            if start == -1:
                # No occurrence of seq[0] here or after
                break
        # Now try to find the full sequence after this start
        pos = start
        found = True
        for i in range(1, m):
            # Move to next occurrence of seq[i] after pos
            if pos + 1 > n:
                found = False
                break
            pos = next_pos[seq[i]][pos + 1]
            if pos == -1:
                found = False
                break
        if found:
            # substring is from start to pos (inclusive)
            return text[start:pos+1]

    return ""

