from typing import Callable

def filter_data(
    data: dict[str, dict],
    criteria: dict[str, object] = None,
    fields: list[str] = None,
    filter_func: Callable[[dict], bool] = None
) -> dict[str, dict]:
    """
    Filter a mapping of individuals to return a new mapping containing only those individuals who meet specified criteria 
    or satisfy a filter function. Each individual's data in the output includes only the specified fields if given; 
    otherwise, all fields are included.
    """
    if not data:
        return {}

    # Determine which individuals to include
    def matches_criteria(attrs: dict) -> bool:
        if criteria is None:
            return True
        for k, v in criteria.items():
            if attrs.get(k) != v:
                return False
        return True

    result = {}
    for key, attrs in data.items():
        include = False
        if filter_func is not None:
            include = filter_func(attrs)
        else:
            include = matches_criteria(attrs)
        if include:
            if fields is None:
                # Include all attributes
                result[key] = dict(attrs)
            else:
                # Include only specified fields present in attrs
                filtered_attrs = {f: attrs[f] for f in fields if f in attrs}
                result[key] = filtered_attrs

    return result

