def capital_words_spaces(*args):
    # Handle input: either one string argument or one list of strings
    if len(args) != 1:
        # As per spec, no validation, but we expect exactly one argument
        text = ''
    else:
        arg = args[0]
        if isinstance(arg, str):
            text = arg
        elif isinstance(arg, list):
            text = ' '.join(arg)
        else:
            text = ''

    # Step 1: Split the text into tokens of words and spaces
    # We use a pattern that captures sequences of non-space characters (\S+) or sequences of spaces (\s+)
    tokens = re.findall(r'\S+|\s+', text)

    # Step 2: For each word token, split internal concatenated capitalized words
    # We use a regex pattern to split words at boundaries where a capital letter starts a new word
    # Pattern explanation:
    #   [A-Z][a-z]* : a capital letter followed by zero or more lowercase letters
    #   | [a-z]+    : or a sequence of lowercase letters (to capture non-capitalized parts)
    # This splits "HelloWorld" into ["Hello", "World"]
    def split_camel(word):
        # If word is all lowercase or does not start with uppercase, return as is in a list
        if not word or not word[0].isalpha():
            return [word]
        # Find all subwords starting with capital letters or all lowercase runs
        parts = re.findall(r'[A-Z][a-z]*|[a-z]+', word)
        return parts

    # Process tokens: split word tokens into subwords, keep spaces as is
    new_tokens = []
    for tok in tokens:
        if tok.isspace():
            # space token
            new_tokens.append(tok)
        else:
            # word token: split if needed
            parts = split_camel(tok)
            # Insert spaces between parts if multiple parts found
            if len(parts) == 1:
                new_tokens.append(parts[0])
            else:
                # Join parts with a single space between them
                # We do not add extra spaces here, just separate parts by spaces
                # We will handle spacing normalization next
                for i, part in enumerate(parts):
                    if i > 0:
                        new_tokens.append(' ')
                    new_tokens.append(part)

    # Step 3: Normalize spacing before capitalized words that immediately follow another word
    # For every capitalized word that follows another word:
    # - If space before it is missing or multiple spaces, replace preceding spaces with exactly one space
    # - Do not alter other spaces

    # We'll iterate through new_tokens to fix spaces before capitalized words accordingly
    # We define helper functions:
    def is_word(token):
        return bool(token) and not token.isspace()

    def is_capitalized_word(token):
        return is_word(token) and token[0].isupper()

    # We'll build a final list of tokens with normalized spaces
    final_tokens = []
    i = 0
    while i < len(new_tokens):
        token = new_tokens[i]
        if is_capitalized_word(token):
            # Check previous token(s) to see if immediately follows another word
            # We look back skipping spaces to find previous word token
            j = len(final_tokens) - 1
            while j >= 0 and final_tokens[j].isspace():
                j -= 1
            if j >= 0 and is_word(final_tokens[j]):
                # Capitalized word follows another word
                # Check how many spaces precede current token in new_tokens
                # Count spaces before current token in new_tokens:
                # They should be exactly one space
                # If no space or multiple spaces, replace with exactly one space

                # Count spaces tokens before i in new_tokens
                space_count = 0
                k = i - 1
                while k >= 0 and new_tokens[k].isspace():
                    space_count += 1
                    k -= 1

                if space_count == 1:
                    # Exactly one space before capitalized word; keep as is
                    # Append all spaces and the token
