def Odd_Length_Sum(nums: list[int] | tuple[int, ...]) -> int:
    n = len(nums)
    if n == 0:
        return 0

    total_sum = 0
    # For each element nums[i], compute how many odd-length sublists include it.
    # An element at index i is included in sublists starting from start index s in [0..i]
    # and ending at end index e in [i..n-1].
    # Number of sublists including nums[i] = (i+1)*(n - i)
    # We count only those with odd length: length = e - s + 1 is odd.
    # The number of odd-length sublists that include nums[i] can be computed by:
    # Count of (s, e) with s <= i <= e and (e - s + 1) odd.
    #
    # To do this efficiently, we consider parity of s and e:
    # length odd => (e - s + 1) % 2 == 1
    # => e - s is even => e and s have same parity.
    #
    # Number of starts (s) from 0 to i with even parity:
    # even_starts = count of s in [0..i] where s % 2 == 0
    # odd_starts = count of s in [0..i] where s % 2 == 1
    #
    # Number of ends (e) from i to n-1 with even parity:
    # even_ends = count of e in [i..n-1] where e % 2 == 0
    # odd_ends = count of e in [i..n-1] where e % 2 == 1
    #
    # Number of odd length sublists including nums[i] =
    # even_starts * even_ends + odd_starts * odd_ends

    for i in range(n):
        # s in [0..i]
        even_starts = (i // 2) + 1      # number of even indices between 0 and i inclusive
        odd_starts = (i + 1) - even_starts

        # e in [i..n-1]
        length = n - i
        # count even indices in [i..n-1]
        # even indices count = number of even numbers in [i, n-1]
        # To find even_ends:
        # count of even numbers in [start, end] = (end//2) - ((start-1)//2)
        even_ends = ( (n - 1)//2 ) - ( (i - 1)//2 )
        odd_ends = length - even_ends

        count = even_starts * even_ends + odd_starts * odd_ends
        total_sum += nums[i] * count

    return total_sum

