def sum_column(grouped_data, selector=None, column_name=None):
    if column_name is None:
        return 0

    # Determine which groups to include based on `selector`
    # grouped_data: list of (group_key, group_list_of_dicts)
    # selector can be:
    # - None: include all groups
    # - list of strings (group keys): include groups with those keys
    # - slice object: include groups at indices in that slice
    # - list of tuples: each tuple is indices, include groups at those positions

    # First, check the form of grouped_data to confirm it is a list of (key, group)
    # According to examples and spec, grouped_data is a list of groups, where each group is a list of dicts.
    # But the selector can be list of group keys, so we must assume grouped_data is a list of (key, group) pairs,
    # otherwise group keys can't be matched.
    #
    # The specification is ambiguous here, but the examples strongly imply grouped_data is a list of pairs:
    # e.g. grouped_data = [(group_key, group), ...]
    #
    # So we proceed assuming:
    # grouped_data: list of tuples (group_key, group_list_of_dicts)
    #
    # If grouped_data is just a list of groups (no keys), then selector can't be list of keys.
    # Since the spec allows selector to be list of group keys, grouped_data must hold keys.

    # If grouped_data is a list of lists only (no keys), then selector as list of keys cannot be used.
    # We'll assume grouped_data is a list of (key, group_list_of_dicts).
    #
    # So each group is (key, group_list_of_dicts).
    # For selectors by index, index means index in grouped_data.
    # For selectors by key, key means the first element in each group tuple.
    # For selectors by tuples, tuples are indices (one element each tuple), so group at that index.

    # Helper: get groups to sum
    groups_to_sum = []

    if selector is None:
        # all groups
        groups_to_sum = [group for _, group in grouped_data]

    elif isinstance(selector, slice):
        # slice of indices
        sliced = grouped_data[selector]
        groups_to_sum = [group for _, group in sliced]

    elif isinstance(selector, list):
        # could be list of keys (strings) or list of tuples (indices)
        # distinguish by element type
        if not selector:
            # empty list means sum over no groups => sum=0
            return 0

        first_elem = selector[0]

        if isinstance(first_elem, str):
            # list of group keys
            keys_set = set(selector)
            for key, group in grouped_data:
                if key in keys_set:
                    groups_to_sum.append(group)

        elif isinstance(first_elem, tuple):
            # list of tuples: each tuple is indices specifying groups
            # spec says each tuple represents a group position
            # so each tuple has one index, e.g. (0,), (2,)
            # use that index to select group from grouped_data
            for idx_tuple in selector:
                idx = idx_tuple[0]
                group = grouped_data[idx][1]
                groups_to_sum.append(group)

        else:
            # unexpected type, but spec says no validation required
            # just treat as no groups
            return 0

    else:
        # selector is something else - not specified - treat as no groups
        return 0

    # Sum the values of column_name in all dictionaries in the selected groups
    total = 0
    for group in groups_to_sum:
        for record in group:
            total += record[column_name]

    return total

