            digits = arg

    # Case 2: two arguments (n, base)
    elif len(args) == 2:
        n, base = args
        digits = digits_in_base(n, base)

    else:
        # Not specified, but just return False for unexpected input length
        return False

    # Count even digits
    even_count = sum(1 for d in digits if d % 2 == 0)

    # Return True if even_count is even, False otherwise
    return even_count % 2 == 0

