def compute_Last_Digit(*args):
    # Extract a and b from the arguments
    if len(args) == 1 and (isinstance(args[0], (tuple, list)) and len(args[0]) == 2):
        a, b = args[0]
    elif len(args) == 2:
        a, b = args
    else:
        # According to spec, no validation needed; assume correct input.
        a, b = args[0], args[1]

    start, end = min(a, b), max(a, b)

    # If the range includes 0, product ends with 0
    if start <= 0 <= end:
        return 0

    # If range is entirely positive
    if start > 0:
        # If range length >= 5, product will include a multiple of 10 (due to 5 and even numbers), so last digit is 0
        if end - start + 1 >= 5:
            return 0
        else:
            product = 1
            for num in range(start, end + 1):
                product *= num
            return product % 10

    # If range is entirely negative
    # Compute product of absolute values from abs(end) up to abs(start) (since negative numbers decrease)
    # The product is same as product of numbers from abs(start) down to abs(end)
    # But we want from smaller to larger, so from abs(end) to abs(start)
    abs_start, abs_end = abs(start), abs(end)
    lower, upper = min(abs_start, abs_end), max(abs_start, abs_end)

    # If range length >=5 for abs values, product ends with 0
    if upper - lower + 1 >= 5:
        return 0

    product = 1
    for num in range(lower, upper + 1):
        product *= num

    # Determine sign of product
    # Count number of negative factors
    count_neg = end - start + 1  # Number of factors (all negative)
    # product sign is (-1)^(count_neg)
    # last digit changes sign only if product is negative; but last digit modulo 10 is always positive
    # So just compute last digit of absolute product
    last_digit = product % 10
    # But product is negative if count_neg is odd
    # The last digit in base 10 is unaffected by sign for the purposes of this problem,
    # so we return last_digit as is.
    return last_digit

