def dif_Square(*args):
    # Extract the integer n to test according to input rules
    n = None
    if len(args) == 1:
        arg = args[0]
        if isinstance(arg, int):
            n = arg
        elif isinstance(arg, list):
            if len(arg) > 0 and isinstance(arg[0], int):
                n = arg[0]
            else:
                return False
        else:
            return False
    elif len(args) == 2:
        # According to spec, ignore the second argument and treat as dif_Square(n)
        if isinstance(args[0], int):
            n = args[0]
        else:
            return False
    else:
        # If no args or more than 2, no valid input
        return False

    # Now determine if n can be expressed as a² - b² for integers a,b
    # Recall: a² - b² = (a-b)(a+b)
    # This means n = x*y with x = a-b, y = a+b, and (x+y) even (since a,b integers)
    # Equivalently, n = x*y, and x,y have the same parity (both odd or both even)
    # So check if n can be factored into two integers with same parity

    # Special case: n = 0 -> 0 = 0² - 0²
    if n == 0:
        return True

    # We'll find integer factors x,y such that x*y = n and x,y same parity
    # Since a,b integers => (a+b) and (a-b) have same parity => both odd or both even

    abs_n = abs(n)
    # Iterate over all divisors of abs_n (including negative divisors)
    # We'll check pairs (d, n//d) for divisors d
    # For performance, only check positive divisors and consider negative pairs by symmetry
    # Because if (x,y) works, then (-x,-y) works as well.
    # So checking positive divisors is sufficient.

    from math import isqrt

    for d in range(1, isqrt(abs_n) + 1):
        if abs_n % d == 0:
            e = abs_n // d

            # Test pairs (d, e) and (-d, -e)
            for x, y in [(d, e), (-d, -e)]:
                # To get original n, assign sign accordingly
                if x * y == n:
                    # Check parity
                    if (x % 2) == (y % 2):
                        # From x = a-b, y = a+b:
                        # a = (x+y)//2, b = (y - x)//2 must be integers
                        # Since x,y same parity, (x+y) and (y-x) are even => a,b integers
                        return True

    return False

