def next_smallest_palindrome(*args):
    n = args[0]
    if isinstance(n, int):
        n = str(n)
    else:
        n = str(n)

    length = len(n)
    if set(n) == {'9'}:
        # If all digits are 9, next palindrome is 1 followed by zeros and ending with 1
        return int('1' + ('0' * (length - 1)) + '1')

    def make_palindrome(left, length):
        # Construct palindrome by mirroring the left half (including middle if odd length)
        if length % 2 == 0:
            return left + left[::-1]
        else:
            return left + left[:-1][::-1]

    half_len = (length + 1) // 2
    left = n[:half_len]
    # Generate palindrome by mirroring left
    palindrome = make_palindrome(left, length)

    if int(palindrome) > int(n):
        return int(palindrome)

    # If palindrome <= n, increment the left half and mirror again
    left_int = int(left)
    left_int += 1
    left = str(left_int)
    # If incrementing left causes length increase (e.g. 999 -> 1000)
    if len(left) > half_len:
        # This means the number length will increase by 1
        # The smallest palindrome with bigger length is 1 followed by zeros and ending with 1
        return int('1' + ('0' * (length)) + '1')

    palindrome = make_palindrome(left, length)
    return int(palindrome)

