def dict_depth(d: dict, current_depth: int = 1) -> int:
    max_depth = current_depth
    for value in d.values():
        if isinstance(value, dict):
            depth = dict_depth(value, current_depth + 1)
            if depth > max_depth:
                max_depth = depth
        elif isinstance(value, (list, tuple)):
            for item in value:
                if isinstance(item, dict):
                    depth = dict_depth(item, current_depth + 1)
                    if depth > max_depth:
                        max_depth = depth
                elif isinstance(item, (list, tuple)):
                    # Traverse nested lists/tuples without increasing depth
                    stack = [item]
                    while stack:
                        current = stack.pop()
                        for elem in current:
