        arr = args[0]
        bounds = args[1]
        low, high = bounds
    else:
        arr, low, high = args

    # If subarray is empty
    if low > high:
        return 0

    # Subarray length
    length = high - low + 1

    # Binary search for smallest missing in arr[low:high+1]
    # The idea:
    # For a sorted array with no duplicates, if arr[low + mid] == mid, 
    # then missing number must be in right half, else left half.
    left, right = 0, length - 1
    while left <= right:
        mid = (left + right) // 2
        if arr[low + mid] == mid:
            left = mid + 1
        else:
            right = mid - 1

    # After binary search, left is the smallest missing number
    # because arr[low + i] == i for all i < left, 
    # so left is the first index where arr[low + left] != left
    return left

