def permute_string(*args):
    # Normalize input to a single string s
    # Acceptable forms:
    # permute_string(s: str)
    # permute_string(chars: list[str])
    # permute_string(s: str, prefix: str)
    #
    # For all, produce the same output.

    if len(args) == 1:
        arg = args[0]
        if isinstance(arg, str):
            s = arg
            prefix = ""
        elif isinstance(arg, list) and all(isinstance(c, str) and len(c) == 1 for c in arg):
            s = "".join(arg)
            prefix = ""
        else:
            # fallback: treat as string
            s = str(arg)
            prefix = ""
    elif len(args) == 2:
        s, prefix = args
        if not isinstance(s, str):
            s = str(s)
        if not isinstance(prefix, str):
            prefix = str(prefix)
    else:
        # no args or more than 2 args: treat as empty string
        s = ""
        prefix = ""

    # If prefix is not empty, it means we are in recursive calls.
    # Only the top call prints directly.

    def backtrack(remaining, built):
        if not remaining:
            print(built)
        else:
            for i in range(len(remaining)):
                backtrack(remaining[:i] + remaining[i+1:], built + remaining[i])

    # Only top-level call prints
    if prefix == "":
        if s == "":
            print("")
        else:
            backtrack(s, "")
    else:
        backtrack(s, prefix)

