def find_Max(arr):
    left, right = 0, len(arr) - 1

    # If the array is not rotated (last element > first element), max is last element
    if arr[left] < arr[right]:
        return arr[right]

    # Binary search for the maximum element
    while left < right:
        mid = (left + right) // 2
        # If mid element is greater than the rightmost element,
        # max must be at mid or to the right of mid
        if arr[mid] > arr[right]:
            left = mid + 1
        else:
            # max is to the left of mid (including mid-1)
            right = mid

    # After the loop, left == right is the index of the smallest element.
    # Maximum element is just before this index (circularly)
    max_index = left - 1 if left > 0 else len(arr) - 1
    return arr[max_index]

