        return sum(int(d) for d in arg)
    else:
        # Unknown type, treat as 0 per spec no validation needed
        n = 0

    # Now n is an int, sum its digits
    if n == 0:
        return 0
    s = 0
    while n > 0:
        s += n % 10
        n //= 10
    return s

