def sum_Of_product(*args):
    # Handle argument patterns:
    # 1) sum_Of_product(n: int)
    # 2) sum_Of_product(n: int, start: int=0, end: int=None)
    # 3) sum_Of_product(values: list[int], n: int=None, start: int=0, end: int=None)
    # The spec implies the function must handle list[int] argument form, where n can be inferred as len(list)
    # or optionally passed as keyword argument n.
    #
    # Because the signature is sum_Of_product(*args), we cannot get keyword arguments directly.
    # So we only handle positional args here.
    #
    # The spec examples show sum_Of_product([0,1,2], n=3) which would require keyword args.
    # But since the signature is only *args, we cannot receive keyword args.
    # So we must assume if a list is passed, n can be inferred as len(list).
    # If the spec requires n passed explicitly with list, but the signature doesn't allow keyword args,
    # we cannot implement that perfectly.
    #
    # To follow the spec strictly, we will:
    # - If one int argument: n
    # - If two or three int arguments: n, start, end
    # - If one list argument: treat list as indices, infer n = max(i)+1 or len(list). 
    #   The spec says n is inferred as the length of the list or must be consistent with usage.
    #   We'll take n = max(indices)+1 for safety (since binomial coefficients require n >= max i+1).
    #   If start or end specified as additional args, we ignore them because spec says only one list argument.
    #
    # Since the spec examples and clarifications are contradictory regarding keyword arguments with list,
    # we follow only positional args and infer n as above.

    if len(args) == 1 and isinstance(args[0], int):
        n = args[0]
        start, end = 0, n - 1
        # full sum range: return comb(2n, n-1)
        return comb(2*n, n-1)

    elif len(args) >= 2 and isinstance(args[0], int):
        n = args[0]
        start = args[1] if len(args) > 1 else 0
        end = args[2] if len(args) > 2 else n - 1
        # if full range, use identity
        if start == 0 and end == n - 1:
            return comb(2*n, n-1)
        s = 0
        for i in range(start, end + 1):
            s += comb(n, i) * comb(n, i + 1)
        return s

    elif len(args) == 1 and isinstance(args[0], list):
        indices = args[0]
        if not indices:
            return 0  # empty sum
        # infer n as max(i)+1 to be safe for binomial coefficients comb(n,i+1)
        max_i = max(indices)
        n = max_i + 1
        s = 0
        for i in indices:
            s += comb(n, i) * comb(n, i + 1)
        # if indices is exactly range(0, n), return identity
        if sorted(indices) == list(range(0, n)):
            return comb(2*n, n-1)
        return s

    else:
        raise TypeError("Invalid arguments")

