def text_match(*args):
    # Combine all arguments into a single string
    s = ''.join(str(arg) for arg in args)

    # The pattern is 'a' followed by zero or more 'b's, but the matched substring is not immediately followed by another 'b'.
    # Since the entire input string must match the pattern, and there's no character after the input string,
    # this means the string should be 'a' followed by zero or more 'b's, but not followed by 'b' again.
    # If the string ends with one or more 'b's, it is allowed only if the next character is not 'b'.
    # Since the input string is the entire string, the "next character" does not exist.
    # So effectively, the input string must be 'a' followed by zero or more 'b's,
    # and the string itself must not have more than one trailing 'b' if it is followed by another 'b' in the input.
    #
    # The example clarifies:
    # 'a' -> found
    # 'ab' -> found
    # 'abb' -> found
    # 'abbb' -> not matched
    #
    # So 'abbb' has 3 'b's after 'a', which is invalid.
    # So the input string must be 'a' followed by 0,1 or 2 'b's, but not 3 or more.
    #
    # Let's confirm:
    # 'abbb' -> 'a' + 'bbb' (3 b's) -> not matched
    #
    # So the pattern is:
    # 'a' + 'b'{0,2}
    #
    # The pattern: ^ab{0,2}$
    #
    # That matches all of 'a', 'ab', 'abb' but not 'abbb'.
    #
    # This matches the specification:
    # "not immediately followed by another 'b'" means no third 'b' after 'a' + two b's.
    #
    # Use regex to match this pattern exactly.
    import re
    pattern = r'^ab{0,2}$'
    if re.match(pattern, s):
        return 'Found a match!'
    else:
        return 'Not matched!'

