def filter_data(data: dict[str, dict[str, float]], *args):
    # Default: no filtering, include all entries
    height_min = float('-inf')
    height_max = float('inf')
    width_min = float('-inf')
    width_max = float('inf')

    # Try to parse args into the four bounds
    try:
        if len(args) == 1:
            # Single argument, expect ((height_min, height_max), (width_min, width_max))
            arg = args[0]
            if (
                isinstance(arg, tuple) and len(arg) == 2 and
                isinstance(arg[0], tuple) and len(arg[0]) == 2 and
                isinstance(arg[1], tuple) and len(arg[1]) == 2
            ):
                height_min, height_max = arg[0]
                width_min, width_max = arg[1]
            else:
                # Malformed; use no filtering
                pass
        elif len(args) == 2:
            # Two arguments, expect (height_min_max_tuple, width_min_max_tuple)
            h_range, w_range = args
            if (
                isinstance(h_range, tuple) and len(h_range) == 2 and
                isinstance(w_range, tuple) and len(w_range) == 2
            ):
                height_min, height_max = h_range
                width_min, width_max = w_range
            else:
                # Malformed; use no filtering
                pass
        elif len(args) == 4:
            # Four floats: height_min, height_max, width_min, width_max
            height_min, height_max, width_min, width_max = args
        else:
            # Malformed or incomplete; no filtering
            pass

        # Attempt to convert all bounds to float, just in case
        height_min = float(height_min)
        height_max = float(height_max)
        width_min = float(width_min)
        width_max = float(width_max)
    except Exception:
        # On any error, no filtering
        height_min = float('-inf')
        height_max = float('inf')
        width_min = float('-inf')
        width_max = float('inf')

    # Construct filtered dictionary without modifying input
    filtered = {}
    for key, dims in data.items():
        h = dims.get("height")
        w = dims.get("width")
        # Only include if both height and width are within inclusive bounds
        if (
            isinstance(h, (int, float)) and isinstance(w, (int, float)) and
            height_min <= h <= height_max and
            width_min <= w <= width_max
        ):
            filtered[key] = dims.copy()

    return filtered

