def odd_length_sum(arr: list[int] | tuple[int, ...]) -> int:
    n = len(arr)
    total = 0
    for length in range(1, n + 1, 2):  # odd lengths only
        for start in range(n - length + 1):
            sub_sum = 0
            end = start + length
            for i in range(start, end):
                sub_sum += arr[i]
            total += sub_sum
    return total

