def lcm(*args):
    # Extract the two integers a and b from the arguments
    if len(args) == 1 and (isinstance(args[0], (tuple, list))):
        a, b = args[0]
    else:
        a, b = args

    # Compute gcd using Euclid's algorithm
    def gcd(x, y):
        while y:
            x, y = y, x % y
        return abs(x)

    # Compute and return lcm
    return abs(a * b) // gcd(a, b)

