def lucky_num(n):
    # Start with the natural numbers beginning at 1
    numbers = list(range(1, 2 * n * n))  # Start with an overestimate length to ensure enough lucky numbers

    idx = 1  # The index in the list that determines the step to remove elements (0-based indexing)
    while idx < len(numbers):
        step = numbers[idx]
        if step > len(numbers):
            break
        # Remove every step-th number starting from index step-1 (0-based)
        del numbers[step-1::step]
        idx += 1

    # Return exactly n lucky numbers
    return numbers[:n]

