def compute_Last_Digit(*args):
    # Extract dividend and divisor from the input forms
    if len(args) == 1:
        # Single argument, should be tuple or list of two integers
        arg = args[0]
        dividend, divisor = arg[0], arg[1]
    else:
        # Two separate integer arguments
        dividend, divisor = args[0], args[1]

    # Perform floating point division
    result = dividend / divisor

    # Convert to string with sufficient decimal places
    # Use repr to get a precise decimal representation
    s = repr(result)

    if '.' not in s:
        # No fractional part
        return 0

    integer_part, fractional_part = s.split('.', 1)

    # If fractional part is empty, no fractional digits
    if not fractional_part:
        return 0

    # The fractional part may have trailing zeros or might be repeating decimal
    # According to examples, trailing zeros are significant (see 10/2 -> 0)
    # So just take the last character of fractional part as the last digit
    last_digit_char = fractional_part[-1]

    return int(last_digit_char)

