def next_smallest_palindrome(n):
    # Convert input to int, removing leading zeros if str
    if isinstance(n, str):
        n = int(n.lstrip('0') or '0')
    else:
        n = int(n)

    # Special quick cases:
    # If n < 9, next palindrome is n+1
    if n < 9:
        return n + 1

    s = str(n)
    length = len(s)

    # Function to check if a string is palindrome
    def is_palindrome(x):
        return x == x[::-1]

    # Increment a numeric string by 1 and return as string
    def increment_str_num(num_str):
        num_list = list(num_str)
        i = len(num_list) - 1
        carry = 1
        while i >= 0 and carry:
            new_digit = (ord(num_list[i]) - ord('0')) + carry
            carry = new_digit // 10
            num_list[i] = str(new_digit % 10)
            i -= 1
        if carry:
            num_list.insert(0, '1')
        return ''.join(num_list)

    # Generate palindrome by mirroring left half onto right half
    # For odd length, middle is included in left half
    def make_palindrome(left, odd_length):
        if odd_length:
            return left + left[:-1][::-1]
        else:
            return left + left[::-1]

    # Main logic:
    # 1. Split number into left half (including middle if odd)
    # 2. Generate palindrome by mirroring left half
    # 3. If palindrome > n, return it
    # 4. Else, increment left half and mirror again

    odd_length = (length % 2 != 0)
    half_len = (length + 1) // 2  # number of chars in left half

    left = s[:half_len]
    palindrome = make_palindrome(left, odd_length)

    if int(palindrome) > n:
        return int(palindrome)
    else:
        # increment left half and mirror again
        left_inc = increment_str_num(left)

        # If length changed after increment (e.g. 999 -> 1000)
        # then palindrome length increases by 1 or 2
        if len(left_inc) > len(left):
            # This means palindrome length increases (e.g. 999->1001)
            # So palindrome is 1 followed by zeros followed by 1
            return int('1' + ('0' * (length - 1)) + '1')
        else:
            palindrome = make_palindrome(left_inc, odd_length)
            return int(palindrome)

