def find_solution(*args):
    # Normalize input to a, b, n
    if len(args) == 3 and all(isinstance(x, int) for x in args):
        a, b, n = args
    elif len(args) == 2 and isinstance(args[0], tuple) and len(args[0]) == 2 and isinstance(args[1], int):
        a, b = args[0]
        n = args[1]
    elif len(args) == 4 and all(isinstance(x, int) for x in args):
        # a, b, n, start_x
        a, b, n, start_x = args
        # We'll handle start_x by scanning from start_x instead of 0
        x = start_x
        while True:
            numerator = n - a * x
            if b != 0 and numerator % b == 0:
                y = numerator // b
                return (x, y)
            x += 1
        # If b == 0, no solution unless n == a*x, but scanning infinite is not practical,
        # so no solution returned here per spec.
        return None
    else:
        # Unknown form, fallback to no solution
        return None

    # For normal case (a,b,n), start scanning from x=0 upwards
    x = 0
    while True:
        numerator = n - a * x
        if b != 0 and numerator % b == 0:
            y = numerator // b
            return (x, y)
        x += 1
        # If b=0, equation is a*x = n, so x = n/a if a divides n and y can be any integer
        # But per spec we scan x from 0 upwards looking for integer y = (n - a*x)/b,
        # if b=0 no division possible, so no solution found here
        if b == 0:
            # Check if a divides n and x = n/a is integer and x >=0
            if a != 0 and n % a == 0 and n // a >= 0:
                return (n // a, 0)  # y arbitrary, choose 0
            else:
                return None

