def get_total_number_of_sequences(*args):
    # Parse input arguments according to specification
    if len(args) == 0:
        m, n = 0, 0
    elif len(args) == 1:
        # single tuple argument
        if isinstance(args[0], tuple) and len(args[0]) == 2:
            m, n = args[0]
        else:
            # Not specified, but assume invalid input means 0 sequences
            return 0
    elif len(args) == 2:
        m, n = args
    else:
        # More than 2 arguments: invalid input, return 0
        return 0

    # If no elements or length is zero, return 0 sequences
    if m == 0 or n == 0:
        return 0

    # dp[pos][val] = number of valid sequences of length pos starting with val at position pos
    # pos ranges from 1 to n (1-based indexing for convenience)
    # val ranges from 1 to m

    # Initialize dp for position 1: any val in [1..m] is valid as first element
    dp_prev = [1] * (m + 1)  # dp_prev[val], val from 1 to m; dp_prev[0] unused

    for pos in range(2, n + 1):
        dp_curr = [0] * (m + 1)

        # Precompute suffix sums of dp_prev for efficient summation
        # Because for dp_curr[val], we sum over dp_prev[x] where x <= val // 2
        suffix_sum = [0] * (m + 2)  # suffix_sum[x] = sum of dp_prev from x to m
        # Actually we need prefix sums from left: prefix_sum[x] = sum dp_prev[1..x]
        prefix_sum = [0] * (m + 2)
        for i in range(1, m + 1):
            prefix_sum[i] = prefix_sum[i - 1] + dp_prev[i]

        for val in range(1, m + 1):
            # We want dp_prev[x] where x <= val//2
            limit = val // 2
            if limit >= 1:
                dp_curr[val] = prefix_sum[limit]
            else:
                dp_curr[val] = 0

        dp_prev = dp_curr

    return sum(dp_prev[1:]) if n >= 1 else 0

