def dict_depth(*args):
    if len(args) == 1:
        d = args[0]
        current_depth = 1
    else:
        d, current_depth = args

    if not d:
        return current_depth

    max_depth = current_depth
    for v in d.values():
        if isinstance(v, dict):
            depth = dict_depth(v, current_depth + 1)
            if depth > max_depth:
                max_depth = depth
    return max_depth

