def remove_column(*args):
    # Normalize arguments to remove_column(data: object, key: str)
    if len(args) == 2:
        data, key = args
    elif len(args) == 1:
        # If a single argument is passed, it's ambiguous; spec doesn't require handling this.
        # Just treat as data with no key to remove (return deep copy).
        data, key = args[0], None
    else:
        # If more than two args, ignore extras and take first two
        data, key = args[0], args[1]

    if not isinstance(key, str):
        # Spec says key is str; if not, treat as no key (return deep copy)
        key = None

    def _remove_column(obj):
        if isinstance(obj, dict):
            # Create new dict without the specified key, and recurse on values
            return {k: _remove_column(v) for k, v in obj.items() if k != key}
        elif isinstance(obj, list):
            # Recurse on each element and build new list
            return [_remove_column(e) for e in obj]
        elif isinstance(obj, tuple):
            # Recurse on each element and build new tuple
            return tuple(_remove_column(e) for e in obj)
        else:
            # For all other types, return as is (preserved unchanged)
            return obj

    # If key is None or not a string, just return a deep copy (recurse without removing anything)
    if key is None:
        # Deep copy with no removals: just recurse but do not remove keys
        def _copy(obj):
            if isinstance(obj, dict):
                return {k: _copy(v) for k, v in obj.items()}
            elif isinstance(obj, list):
                return [_copy(e) for e in obj]
            elif isinstance(obj, tuple):
                return tuple(_copy(e) for e in obj)
            else:
                return obj
        return _copy(data)

    return _remove_column(data)

