def even_Power_Sum(*args):
    if len(args) != 1:
        return 0

    arg = args[0]
    if isinstance(arg, int):
        n = arg
    elif isinstance(arg, list):
        n = len(arg)
    else:
        return 0

    if n == 0:
        return 0

    # sum of (2*i)^4 for i in 1 to n
    # (2*i)^4 = 16 * i^4
    # so sum = 16 * sum(i^4 for i=1 to n)

    # Use formula for sum of fourth powers:
    # sum_{i=1}^n i^4 = n(n+1)(2n+1)(3n^2+3n-1) / 30
    sum_i4 = n * (n + 1) * (2 * n + 1) * (3 * n * n + 3 * n - 1) // 30

    return 16 * sum_i4

