def odd_length_sum(arr: list[int]) -> int:
    # Convert input to list if not already a list
    if not isinstance(arr, list):
        arr = list(arr)
    n = len(arr)
    if n == 0:
        return 0

    total = 0
    for i in range(n):
        for length in range(1, n - i + 1, 2):  # Only odd lengths
            total += sum(arr[i:i+length])
    return total

