def lcm(*args):
    # Extract two integers from the arguments
    if len(args) == 1:
        # Single argument: must be a tuple or list of two integers
        a, b = args[0]
    else:
        # Two separate integer arguments
        a, b = args

    # Handle zero case
    if a == 0 or b == 0:
        return 0

    # Compute gcd using Euclid's algorithm
    def gcd(x, y):
        while y:
            x, y = y, x % y
        return x

    a_abs, b_abs = abs(a), abs(b)
    return (a_abs // gcd(a_abs, b_abs)) * b_abs

