def substract_elements(t1: tuple[float, ...], t2: tuple[float, ...] = ()) -> tuple[float, ...]:
    length = len(t1)
    # If t2 is empty, treat as zeros
    if not t2:
        t2 = (0,) * length
    else:
        # If t2 shorter than t1, pad with zeros
        if len(t2) < length:
            t2 = t2 + (0,) * (length - len(t2))

    result = []
    for a, b in zip(t1, t2):
        diff = a - b
        # Determine type to preserve int or float per element
        # If both are int and difference is int, keep int
        if isinstance(a, int) and isinstance(b, int):
            diff = int(diff)
        else:
            diff = float(diff)
        result.append(diff)
    return tuple(result)

