def lucky_num(n: int = 10):
    if n == 0:
        return []

    # Start with an initial list long enough to find n lucky numbers.
    # Since lucky numbers are sparse, we start with a list larger than n.
    # We'll increase the range if needed.
    length = max(50, n * 10)

    while True:
        # Initialize the list of odd numbers starting with 1
        numbers = list(range(1, length + 1, 2))

        idx = 1  # start with second element's value as step (the first lucky number is 1, skip that)
        while idx < len(numbers):
            step = numbers[idx]
            if step > len(numbers):
                break
            # Remove every step-th number starting from step-1 index (0-based)
            # Because the step-th number in 1-based indexing corresponds to index step-1 in 0-based indexing
            numbers = [num for i, num in enumerate(numbers) if (i + 1) % step != 0]
            idx += 1

        if len(numbers) >= n:
            return numbers[:n]
        # Increase length and try again if not enough lucky numbers found
        length *= 2

