def get_noOfways(*args):
    # Determine n based on input rules
    if len(args) != 1:
        n = 0
    else:
        arg = args[0]
        if isinstance(arg, int):
            n = arg
        elif isinstance(arg, (tuple, list)) and len(arg) == 1 and isinstance(arg[0], int):
            n = arg[0]
        else:
            n = 0

    if n == 0:
        return 0
    if n == 1:
        return 1

    # Calculate the number of ways using Fibonacci-like sequence:
    # get_noOfways(0) = 0
    # get_noOfways(1) = 1
    # get_noOfways(n) = get_noOfways(n-1) + get_noOfways(n-2)
    a, b = 0, 1
    for _ in range(2, n + 1):
        a, b = b, a + b
    return b

