            if isinstance(first, int):
                n = first
    elif len(args) > 1:
        # Use the first int argument found
        for arg in args:
            if isinstance(arg, int):
                n = arg
                break

    # If no int found, return False (not specified what to do, but safest)
    if n is None:
        return False

    # Key mathematical fact:
    # An integer n can be represented as a difference of two squares:
    # n = a² - b² = (a+b)(a-b)
    #
    # So n must be factorable into two integers x = (a+b), y = (a-b) such that:
    # n = x * y, and (x + y) and (x - y) are both even (since a = (x+y)/2, b = (x-y)/2).
    #
    # This means x and y have the same parity (both even or both odd).
    #
    # Thus, n can be represented as difference of squares if and only if
    # n can be factored into two integers of the same parity.
    #
    # Special cases:
    # - n = 0 trivially True (0=0²-0²)
    #
    # Let's check this by iterating over all factor pairs of n.

    # For 0, return True immediately
    if n == 0:
        return True

    # We'll check for all divisors d of n (positive or negative),
    # and the corresponding divisor n//d, to see if they have same parity.

    # Since negative factors mirror positive factors, we can just check positive divisors,
    # then consider their negative counterparts via parity check.

    abs_n = abs(n)
    # If n = 1 or -1: 
    # Factors are ±1, ±1, same parity (odd, odd) => True
    # If n = 2 or -2:
    # Factors are ±1, ±2 (1 and 2 differ parity) so not representable.
    # But let's do the general check.

    # To efficiently check factors:
    from math import isqrt
    for d in range(1, isqrt(abs_n) + 1):
        if abs_n % d == 0:
            x, y = d, abs_n // d

            # Since n can be negative, consider both (x,y) and (-x,-y) to get n
            # Check pairs (x,y) and (-x,-y):
            # If n > 0, n = x*y or (-x)*(-y) = x*y, same product.
            # If n < 0, n = (-x)*y or x*(-y), so we must consider sign swaps.
            # To handle sign for negative n:
            # For positive n, check (x,y) parity.
            # For negative n, check (x,-y) and (-x,y) parity.

            # Helper to check parity of two numbers:
            def same_parity(a, b):
                return (a % 2) == (b % 2)

            # For positive n:
            if n > 0:
                if same_parity(x, y):
                    return True
                if same_parity(-x, -y):
                    return True  # same parity as above, redundant but safe
            else:
                # n < 0
                # Check (x, -y)
                if same_parity(x, -y):
                    return True
                # Check (-x, y)
                if same_parity(-x, y):
                    return True

    # If no factor pairs with same parity found, return False
    return False

