def find_solution(*args):
    # Parse input to get a, b, n
    if len(args) == 3:
        a, b, n = args
    else:  # len(args) == 2
        (a, b), n = args

    # Handle the case a == 0 separately to avoid division/mod by zero
    if a == 0:
        # Equation reduces to b*y = n
        if b == 0:
            # a=b=0, equation 0*x + 0*y = n
            # Only solution if n == 0
            if n == 0:
                return (0, 0)
            else:
                # No solution
                # Spec does not say what to do, but since no solution, no return
                # So let's just return None or raise, but spec doesn't say, so no return.
                # We assume inputs are such that a solution exists.
                return None
        else:
            # b*y = n => y = n // b if divisible
            if n % b == 0:
                return (0, n // b)
            else:
                return None

    # Otherwise, iterate over nonnegative x starting from 0
    x = 0
    while True:
        rhs = n - a * x
        # Check if rhs divisible by b
        if b != 0 and rhs % b == 0:
            y = rhs // b
            return (x, y)
        x += 1

