def next_power_of_2(n):
    # If n is a list, use the first element
    if isinstance(n, list):
        n = n[0]
    # n is now int or float
    # For n <= 1, return 1
    if n <= 1:
        return 1
    # Find the smallest power of two >= n
    # Use bit_length on the integer ceiling of n if n is float
    import math
    val = n
    if not isinstance(val, int):
        val = math.ceil(val)
    # If val is already a power of two, return val
    if val & (val - 1) == 0:
        return val
    # Otherwise, find next power of two using bit_length
    return 1 << val.bit_length()

