def get_total_number_of_sequences(*args):
    # Parse input arguments
    if len(args) == 1 and isinstance(args[0], tuple):
        n, m = args[0]
    else:
        n, m = args

    # If sequence length is 1, all single elements from 1 to m are valid
    if n == 1:
        return m

    # dp[i][x] = number of valid sequences of length i ending with x
    # i ranges from 1 to n, x ranges from 1 to m
    dp = [ [0] * (m+1) for _ in range(n+1) ]

    # Base case: sequences of length 1
    for x in range(1, m+1):
        dp[1][x] = 1

    # Fill dp for lengths 2 to n
    for i in range(2, n+1):
        # Precompute prefix sums for dp[i-1] to optimize summation
        prefix_sum = [0] * (m+2)
        for x in range(1, m+1):
            prefix_sum[x] = prefix_sum[x-1] + dp[i-1][x]

        for x in range(1, m+1):
            # Previous element p must satisfy:
            # 2 * p <= x  => p <= x // 2
            max_p = x // 2
            if max_p >= 1:
                dp[i][x] = prefix_sum[max_p]
            else:
                dp[i][x] = 0

    # Total sequences of length n is sum over all possible last elements
    return sum(dp[n][1:])

