def dict_depth(*args):
    # Handle flexible arguments as per the rules
    # If called with one argument and it's a dict, use it directly
    # If called with two arguments, ignore the second and use only the first argument (the dict)
    # If called with other forms, also extract the first dict argument.
    # This ensures the function works for calls like dict_depth(d), dict_depth(d, current_depth)
    if len(args) == 0:
        # No arguments, return 0 by default or raise?
        # Spec does not say, but since no input validation is required,
        # assume empty dict as default
        d = {}
    else:
        d = args[0]

    # Base case: depth is at least 1 (the dictionary itself)
    if not isinstance(d, dict):
        # Spec does not require validation, but if not dict, depth is 0
        # However, this case should not occur according to spec
        return 0

    if not d:
        return 1

    max_child_depth = 0
    for v in d.values():
        if isinstance(v, dict):
            child_depth = dict_depth(v)
            if child_depth > max_child_depth:
                max_child_depth = child_depth

    return 1 + max_child_depth

