def smallest_missing(arr):
    # Since the array is sorted, we can iterate through it and track the smallest missing nonnegative integer.
    missing = 0
    for num in arr:
        if num < 0:
            continue
        if num == missing:
            missing += 1
        elif num > missing:
            # Since arr is sorted, if num > missing, missing is not in arr
            break
    return missing

