def permute_string(*args):
    # Normalize inputs to s: str
    # Acceptable calls:
    #   permute_string(s: str)
    #   permute_string(chars: list[str])
    #   permute_string(s: str, prefix: str='')
    #   permute_string(chars: list[str], prefix: str='')
    #
    # The function returns a list of all permutations of the string s (or chars joined),
    # including duplicates, with no specified order.

    # Parse arguments
    if len(args) == 0:
        # No input, return empty list
        return []
    elif len(args) == 1:
        # One argument: either str or list[str]
        arg = args[0]
        if isinstance(arg, str):
            s = arg
            prefix = ''
        elif isinstance(arg, list) and all(isinstance(c, str) and len(c) == 1 for c in arg):
            s = ''.join(arg)
            prefix = ''
        else:
            # Unexpected type, treat as empty input per spec (no validation requested)
            return []
    elif len(args) == 2:
        # Two arguments: (s, prefix)
        arg1, arg2 = args
        if isinstance(arg1, str) and isinstance(arg2, str):
            s = arg1
            prefix = arg2
        elif (isinstance(arg1, list) and all(isinstance(c, str) and len(c) == 1 for c in arg1)
              and isinstance(arg2, str)):
            s = ''.join(arg1)
            prefix = arg2
        else:
            return []
    else:
        # More than 2 arguments - invalid for our function
        return []

    # Recursive helper function to generate permutations of s with prefix
    def helper(remaining, current_prefix):
        if not remaining:
            return [current_prefix]
        result = []
        for i, ch in enumerate(remaining):
            # Remove character at i and recurse
            result.extend(helper(remaining[:i] + remaining[i+1:], current_prefix + ch))
        return result

    return helper(s, prefix)

