def find_Max(arr):
    left, right = 0, len(arr) - 1

    # If array is not rotated (strictly ascending)
    if arr[left] < arr[right]:
        return arr[right]

    while left < right:
        mid = (left + right) // 2

        # If mid element is greater than its next element,
        # mid element is the maximum
        if mid < right and arr[mid] > arr[mid + 1]:
            return arr[mid]

