def move_num(*args):
    # Initialize s1 and s2 with defaults
    s1 = ""
    s2 = ""

    # Parse args according to specification
    if len(args) == 0:
        # no arguments
        s1 = ""
        s2 = ""
    elif len(args) == 1:
        # one argument, which should be a tuple of two strings
        tup = args[0]
        if (isinstance(tup, tuple) or isinstance(tup, list)) and len(tup) == 2:
            s1, s2 = tup
            # s1 expected to be str, s2 expected to be str
            if not isinstance(s1, str):
                s1 = str(s1)
            if not isinstance(s2, str):
                s2 = str(s2)
        else:
            # treat single argument as s1, s2 defaults to empty string
            s1 = str(tup)
            s2 = ""
    else:
        # two or more arguments, take first two
        s1 = args[0]
        s2 = args[1]
        if not isinstance(s1, str):
            s1 = str(s1)
        if isinstance(s2, list):
            # join list of strings into one string
            s2 = "".join(str(x) for x in s2)
        elif not isinstance(s2, str):
            s2 = str(s2)

    # Extract digits from s1
    digits = "".join(c for c in s1 if c.isdigit())
    s1_no_digits = "".join(c for c in s1 if not c.isdigit())
    s2_with_digits = s2 + digits

    return (s1_no_digits, s2_with_digits)

