def filter_data(*args):
    # If no arguments, return empty dict
    if not args:
        return {}

    # Helper function to check if a value is a dict with exactly 'height' and 'width' keys
    def is_height_width_dict(d):
        return isinstance(d, dict) and set(d.keys()) == {'height', 'width'} and \
               isinstance(d['height'], int) and isinstance(d['width'], int)

    # Case 1: single argument
    if len(args) == 1:
        data = args[0]
        # If not a dict, return empty
        if not isinstance(data, dict):
            return {}

        # Check if the dict itself is a height/width dict (not student IDs)
        if set(data.keys()) == {'height', 'width'} and \
           isinstance(data['height'], int) and isinstance(data['width'], int):
            # Per spec, treat as empty input and return {}
            return {}

        # Now data is dict with keys as student IDs and values as either:
        # a) dict with keys 'height' and 'width' (both int)
        # b) tuple of two ints (height, width)

        result = {}
        for student_id, val in data.items():
            if isinstance(val, dict):
                # Check if dict with keys height and width and int values
                if is_height_width_dict(val):
                    result[student_id] = {'height': val['height'], 'width': val['width']}
                else:
                    # If not proper dict, ignore entry
                    continue
            elif isinstance(val, tuple) and len(val) == 2 and \
                 all(isinstance(x, int) for x in val):
                result[student_id] = {'height': val[0], 'width': val[1]}
            else:
                # Invalid entry, ignore
                continue

        return result

    # Case 2: two arguments
    if len(args) == 2:
        heights, widths = args
        # Both must be dicts mapping student IDs to int
        if not (isinstance(heights, dict) and isinstance(widths, dict)):
