def check_Even_Parity(*args):
    if len(args) != 1:
        return  # behavior not specified, do nothing

    x = args[0]

    if isinstance(x, int):
        n = abs(x)
        # binary representation without '0b'
        bits = bin(n)[2:] if n != 0 else "0"
        count_ones = bits.count('1')
    elif isinstance(x, str):
        # string representing binary digits '0' or '1'
        count_ones = x.count('1')
    elif isinstance(x, list):
        # list of integers 0 or 1
        count_ones = sum(x)
    else:
        return  # unsupported type, behavior not specified

    return (count_ones % 2) == 0

