def compute_Last_Digit(*args):
    # Parse inputs to get a and b
    if len(args) == 1:
        # Single argument, should be tuple or list of two integers
        pair = args[0]
        a, b = pair[0], pair[1]
    else:
        # Two arguments
        a, b = args[0], args[1]

    # Compute the last digit of (b! / a!) = product of integers from (a+1) to b
    # Since a! divides b! exactly, this is an integer

    # If a == b, quotient is 1, last digit = 1
    if a == b:
        return 1

    # Compute last digit of product (a+1)*(a+2)*...*b modulo 10
    last_digit = 1
    for x in range(a+1, b+1):
        last_digit = (last_digit * (x % 10)) % 10

    return last_digit

