def dif_Square(*args):
    # Helper function to test a single integer n with optional limit
    def can_represent(n, limit=None):
        if isinstance(n, int) == False:
            return False
        # If negative, return False directly (no nonnegative a,b can produce negative difference)
        if n < 0:
            return False
        # If n == 0, always True since 0^2 - 0^2 = 0
        if n == 0:
            return True

        # If limit is None, we choose a suitable search range:
        # maximum a needed is at least ceil(sqrt(n)) + 1
        # because a^2 - b^2 = (a-b)(a+b) = n
        # a^2 - b^2 = n => a^2 = n + b^2
        # For b=0, a^2 = n, so a = sqrt(n)
        # So a can be at max sqrt(n) + some margin.
        # We'll just set max_a = int(n**0.5) + 1

        max_a = limit if limit is not None else int(n**0.5) + 1

        # Iterate over possible a from 0 to max_a
        for a in range(max_a + 1):
            a2 = a * a
            b2 = a2 - n
            if b2 < 0:
                continue
            # Check if b2 is a perfect square
            b = int(b2**0.5)
            if b * b == b2:
                # Check limit if given
                if limit is not None and (b > limit or a > limit):
                    continue
                # Found valid a,b
                return True
        return False

    # Parse args
    if len(args) == 1:
        arg = args[0]
        if isinstance(arg, list):
            # List of integers
            return [can_represent(x) for x in arg]
        else:
            # Single integer with no limit
            return can_represent(arg)
    elif len(args) == 2:
        n, limit = args
        return can_represent(n, limit)
    else:
        # No valid call, but specification does not require validation, so return False
        return False

