def get_total_number_of_sequences(*args):
    # Parse input arguments according to specification:
    # Either get_total_number_of_sequences(n, m) or get_total_number_of_sequences((n, m))
    if len(args) == 1 and isinstance(args[0], tuple):
        n, m = args[0]
    else:
        n, m = args

    # Edge cases
    if n == 1:
        # Any number from 1 to m can be the sequence of length 1
        return m
    if m == 0:
        return 0

    # dp[i][x] := number of sequences of length i that end with value x
    # We need sequences of length n, values in [1,m]
    # For i=1, dp[1][x] = 1 for all x in [1,m]
    # For i>1, dp[i][x] = sum of dp[i-1][y] over all y such that 
    # x >= 2*y and y in [1,m]

    # Initialize dp for length 1
    dp_prev = [0] + [1] * m  # 1-based indexing, dp_prev[x] for x in [1..m]

    for i in range(2, n + 1):
        dp_curr = [0] * (m + 1)
        # For each x in [1..m], find all y in [1..m] with 2*y <= x
        # Since y >=1, y <= x//2
        # So sum dp_prev[y] for y in 1..x//2
        prefix_sum = [0] * (m + 1)
        for idx in range(1, m + 1):
            prefix_sum[idx] = prefix_sum[idx - 1] + dp_prev[idx]

        for x in range(1, m + 1):
            limit = x // 2
            if limit >= 1:
                dp_curr[x] = prefix_sum[limit]
            else:
                dp_curr[x] = 0
        dp_prev = dp_curr

    return sum(dp_prev[1:])  # sum over all valid last elements

