def text_match_two_three(s: str, min_b: int = 2, max_b: int = 3) -> bool:
    if not s:
        return False
    n = len(s)
    for i in range(n):
        if s[i] == 'a':
            count_b = 0
            j = i + 1
            while j < n and s[j] == 'b' and count_b < max_b:
                count_b += 1
                j += 1
            if min_b <= count_b <= max_b:
                return True
    return False

