def dict_depth(*args):
    # Normalize input to accept only dict_depth(d)
    if len(args) == 1 and isinstance(args[0], dict):
        d = args[0]
    else:
        # If called with other forms, extract dict from args
        # According to the rules: write one function dict_depth that accepts every form
        # but always compute depth from the dict argument only.
        # If no dict found, treat as empty dict.
        d = None
        for arg in args:
            if isinstance(arg, dict):
                d = arg
                break
        if d is None:
            d = {}

    # Base case: empty dict has depth 1
    if not d:
        return 1

    max_nested_depth = 0
    for v in d.values():
        if isinstance(v, dict):
            depth_v = dict_depth(v)
            if depth_v > max_nested_depth:
