def permute_string(seq):
    # Handle empty input case
    if not seq:
        return [seq]

    is_str = isinstance(seq, str)
    elements = list(seq)

    elements.sort()
    used = [False] * len(elements)
    res = []

    def backtrack(path):
        if len(path) == len(elements):
            if is_str:
                res.append(''.join(path))
            else:
                res.append(path[:])
            return
        for i in range(len(elements)):
            if used[i]:
                continue
            # Skip duplicates
            if i > 0 and elements[i] == elements[i - 1] and not used[i - 1]:
                continue
            used[i] = True
            path.append(elements[i])
            backtrack(path)
            path.pop()
            used[i] = False

    backtrack([])
    return res

