        # No arguments -> empty list
        return []
    elif len(args) == 1:
        # One argument: expect a tuple (rows, cols)
        size = args[0]
        if isinstance(size, tuple) and len(size) == 2 and all(isinstance(x, int) for x in size):
            rows, cols = size
            return [[0]*cols for _ in range(rows)]
        else:
            # Not specified, but no validation needed - fallback empty
            return []
    elif len(args) == 2:
        first, second = args
        if isinstance(first, int) and isinstance(second, int):
            # two integers: rows, cols
            rows, cols = first, second
            return [[0]*cols for _ in range(rows)]
        elif isinstance(first, list) and all(isinstance(x, int) for x in first) and isinstance(second, int):
            # list of ints and cols
            data, cols = first, second
            rows = (len(data) + cols - 1) // cols  # ceil division
            result = []
            for r in range(rows):
                start = r*cols
                end = start + cols
                row = data[start:end]
                # Pad last row if needed
                if len(row) < cols:
                    row = row + [0]*(cols - len(row))
                result.append(row)
            return result
        else:
            # Unspecified input form -> empty list fallback
            return []
    else:
        # More than 2 arguments - not specified, fallback empty list
        return []

