def find_Max(*args):
    if len(args) == 1:
        arr = args[0]
        start, end = 0, len(arr) - 1
    else:
        arr, start, end = args

    subarr = arr[start:end+1]
    if not subarr:
        return None  # If subrange is empty, though spec does not specify behavior.

    # Since the sequence is ordered then rotated, the max is either:
    # - The element before the rotation point (the largest element)
    # - Or if the subrange does not include rotation, just max in subrange.
    #
    # To find max in O(log n), we can do a binary search for max:
    # The max is the element where next element is smaller (rotation point).
    # But we must apply this logic only on the subrange.

    low, high = 0, len(subarr) - 1

    # If subarr is strictly ascending or only one element, max is last element
    if subarr[low] < subarr[high]:
        return subarr[high]

    while low < high:
        mid = (low + high) // 2
        # if mid element is greater than next element, mid element is max
        if mid < len(subarr) - 1 and subarr[mid] > subarr[mid + 1]:
            return subarr[mid]
        # if mid element is less than previous element, previous is max
        if mid > 0 and subarr[mid] < subarr[mid - 1]:
            return subarr[mid - 1]

        # Decide which side to move to
        if subarr[mid] > subarr[low]:
            # max is to the right of mid
            low = mid + 1
        else:
            # max is to the left of mid
            high = mid - 1

    # After loop low == high, return that element
    return subarr[low]

