def str_to_tuple(*args):
    # Accept either str_to_tuple(s: str) or str_to_tuple(numbers: list[int]) or similar
    # Normalize input to a single string s
    if len(args) == 1:
        arg = args[0]
        if isinstance(arg, str):
            s = arg
        elif isinstance(arg, (list, tuple)):
            # If input is a list or tuple of integers, convert them to string joined by spaces
            s = ' '.join(str(x) for x in arg)
        else:
            # If input is a single int or other type, convert to string
            s = str(arg)
    else:
        # Multiple arguments: treat as sequence of numbers, convert to string joined by spaces
        s = ' '.join(str(x) for x in args)

    # Extract numbers from the string s
    # Numbers can be separated by any non-digit characters, including spaces, commas, etc.
    numbers = re.findall(r'\d+', s)
    return tuple(int(num) for num in numbers)

