import re

def capital_words_spaces(*args):
    # Accept exactly one argument, either a string or list of strings
    text = args[0]
    if isinstance(text, list):
        # Join list of strings without spaces before processing
        text = ''.join(text)
    # Define a pattern to find words starting with capital letter A-Z followed by letters
    # We will split the text into tokens: capitalized words and the rest
    # The goal is to insert spaces before each capitalized word except the first

    # Use re.finditer to identify capitalized words
    pattern = re.compile(r'[A-Z][a-zA-Z]*')
    result = []
    last_end = 0
    first_capital_word_found = False

    for match in pattern.finditer(text):
        start, end = match.span()
        # Append text between last_end and start (non-capitalized parts)
        if start > last_end:
            result.append(text[last_end:start])
        # For the capitalized word, decide whether to prepend a space
        if not first_capital_word_found:
            # First capitalized word: no leading space
            result.append(text[start:end])
            first_capital_word_found = True
        else:
            # Insert a space before capitalized word
            result.append(' ' + text[start:end])
        last_end = end
    # Append remaining text after last match
    if last_end < len(text):
        result.append(text[last_end:])
    return ''.join(result)

