def odd_length_sum(arr):
    n = len(arr)
    if n == 0:
        return 0

    total = 0
    for i, val in enumerate(arr):
        # Number of subarrays including arr[i]
        total_subarrays = (i + 1) * (n - i)
        # Number of odd-length subarrays including arr[i]
        odd_count = (total_subarrays + 1) // 2
        total += val * odd_count
    return total

