import string

def length_Of_Last_Word(*args):
    if len(args) != 1:
        return 0

    text = args[0]

    if isinstance(text, list):
        text = " ".join(text)
    elif not isinstance(text, str):
        return 0

    text = text.rstrip()
    if not text:
        return 0

    words = text.split()
    if not words:
        return 0

    last_word = words[-1]

    # Strip trailing punctuation characters
    last_word = last_word.rstrip(string.punctuation)

    return len(last_word)

