from collections.abc import Iterable
from numbers import Number

def substract_elements(values):
    # Determine the type of the current level container to reconstruct output with the same type
    container_type = type(values)

    # Convert to list for easy indexing and length check
    elems = list(values)

    # If fewer than 2 elements, return empty collection of same type
    if len(elems) < 2:
        if container_type is tuple:
            return ()
        elif container_type is list:
            return []
        else:
            # For other iterables, try to reconstruct empty of the same type if possible
            # For general iterables, returning empty list is a safe fallback
            try:
                return container_type()
            except Exception:
                return []

    # Helper function to process an element: if iterable (but not string/bytes), recurse, else numeric pass as-is
    def process_element(el):
        if isinstance(el, Iterable) and not isinstance(el, (str, bytes)):
            return substract_elements(el)
        else:
            return el

    # Process elements first to get either numeric values or nested difference lists/tuples
    processed = [process_element(e) for e in elems]

    # Now compute differences between consecutive elements.
    # Differences only make sense between numeric elements at this level.
    # According to spec, each element is either numeric or nested collection.
    # At this level, after processing, elements are either numeric or nested difference collections.
    # We only subtract numeric elements to form differences.
    # If elements are nested collections (like lists/tuples), they are not subtracted but replaced by their difference collection.
    # So at this level, the processed elements are all either numeric or nested difference collections.
    # But per spec, the output at this level is differences between consecutive numeric elements.
    # The spec examples show that nested collections are not subtracted with numeric elements at same level.
    # So to handle this, we consider that all elements are numeric or nested collections.
    # Differences are only computed if both consecutive elements are numeric.
    # If either element is a nested collection, difference at that position is an empty collection of that nested element's type.
    # But examples show that nested collections appear as is, and differences are computed inside them.
    # Actually, from examples:
    # substract_elements([1, [2,4,7], 10]) -> [[], [2,3], []]
    # So at top level, elements: 1 (numeric), [2,4,7] (nested), 10 (numeric)
    # Differences between 1 and [2,4,7] => empty list []
    # Differences between [2,4,7] and 10 => empty list []
    # So when elements are of mixed type, the difference is empty collection of the same type as the next element.
    # So difference between element_i and element_i+1:
    # - if both numeric: element_i+1 - element_i
    # - if either is nested collection: return empty collection of the same type as element_i+1

    diffs = []
    for i in range(len(processed)-1):
        a = processed[i]
        b = processed[i+1]
        # Check if both numeric
        if isinstance(a, Number) and isinstance(b, Number):
            diffs.append(b - a)
        else:
            # Return empty collection of same type as b if b is iterable (not string/bytes), else empty list
            if isinstance(b, Iterable) and not isinstance(b, (str, bytes)):
                try:
                    diffs.append(type(b)())
                except Exception:
                    diffs.append([])
            else:
                # b is numeric or non-iterable; difference undefined, return empty list
                diffs.append([])

    # Reconstruct output with same container type
    if container_type is tuple:
        return tuple(diffs)
    elif container_type is list:
        return diffs
    else:
        try:
            return container_type(diffs)
        except Exception:
            return diffs

