    numbers = list(range(1, limit + 1))

    # The lucky number sieve:
    # The first lucky number is 1 (numbers[0])
    # Then starting from index 1, use numbers[i] as the step to remove elements.
    idx = 1
    while idx < len(numbers):
        step = numbers[idx]
        if step > len(numbers):
            break
        # Remove every step-th number from the list, starting from index step-1
        # (because list is 0-indexed)
        del numbers[step - 1::step]
        idx += 1

    # Return the first n lucky numbers
    return numbers[:n]

