    for arg in args:
        if isinstance(arg, int):
            n = arg
            break

    # Base cases
    if n == 0:
        return 1
    if n == 1:
        return 1

    # Use dynamic programming to calculate the number of ways:
    # This is the (n+1)th Fibonacci number with base cases f(0)=1, f(1)=1
    prev, curr = 1, 1
    for _ in range(2, n + 1):
        prev, curr = curr, prev + curr
    return curr

