def get_gcd(arr):
    from math import gcd
    if not arr:
        return 0
    abs_vals = [abs(x) for x in arr]
    current_gcd = 0
    for val in abs_vals:
        current_gcd = gcd(current_gcd, val)
    return current_gcd

