def compute_Last_Digit(*args):
    # Unpack inputs to get integers a and b
    if len(args) == 1 and (isinstance(args[0], (tuple, list)) and len(args[0]) == 2):
        a, b = args[0]
    else:
        a, b = args

    # Determine smaller and larger
    small, large = min(a, b), max(a, b)

    # The quotient is factorial(large) // factorial(small)
    # = product of integers from small+1 to large inclusive
    # We only need the last digit of this product

    last_digit = 1
    for x in range(small + 1, large + 1):
        last_digit = (last_digit * (x % 10)) % 10

    return last_digit

