def find_solution(*args):
    # Normalize input to (a, b, n)
    if len(args) == 3:
        a, b, n = args
    elif len(args) == 2 and isinstance(args[0], tuple):
        (a, b), n = args
    else:
        raise TypeError("Invalid arguments")

    # Handle the case b == 0 separately to avoid division by zero
    if b == 0:
        # Equation: a*x = n
        # x must be integer >= 0 and y can be any integer (but we need integer y)
        # So y can be any integer, but since y must be integer, we just check if a*x = n
        # We try x from 0 upwards: a*x = n => x = n/a (if a divides n)
        # Since x must be integer >= 0
        if a == 0:
            # Then equation is 0*x + 0*y = n, so if n == 0, any x,y satisfy
            # Return (0,0)
            return (0, 0) if n == 0 else None
        if n % a == 0:
            x = n // a
            if x >= 0:
                # y can be any integer, pick y=0
                return (x, 0)
        return None

    # For b != 0, iterate over x from 0 upwards, check if (n - a*x) divisible by b
    # We limit the search to some reasonable upper bound to avoid infinite loops in theory,
    # but problem does not specify any bound.
    # Since the problem does not specify, we search until we find a solution or conclude no solution.
    # In theory, for Diophantine equations, solution exists iff gcd(a,b) divides n.

    from math import gcd
    g = gcd(a, b)
    if n % g != 0:
        return None  # no solution exists

    # Try x from 0 upwards
    # Since b != 0, y = (n - a*x) / b must be integer
    # To avoid infinite loop, we can consider that x must satisfy (n - a*x) % b == 0
    # A solution exists modulo b/g, so upper bound can be b//g (or abs(b)//g)
    # But safest is to try x in range(0, abs(b)+1) * (abs(b) maybe)
    # Because y = (n - a*x)/b integer => (n - a*x) mod b == 0
    # So the pattern repeats every abs(b)//g values of x

    step = abs(b) // g
    max_iter = step  # scanning x from 0 to step-1 covers all residue classes mod step

    for x in range(max_iter):
        numerator = n - a * x
        if numerator % b == 0:
            y = numerator // b
            return (x, y)

    return None

