                # empty list, treat as n=0
                n = 0
        else:
            # Single int or float convertible to int
            n = int(first)

    # According to spec, n is integer after conversion
    # Handle the case n <= 0 by returning 1 (since smallest power of 2 >= n is 1)
    if n <= 0:
        return 1

    # Check if n is already a power of two
    # A number n > 0 is a power of two iff (n & (n-1)) == 0
    if (n & (n - 1)) == 0:
        return n

    # Otherwise, find the next power of two greater than n
    # One method: find bit length of n
    # The next power of two is 1 shifted left by n.bit_length()
    return 1 << n.bit_length()

