def get_total_number_of_sequences(*args):
    # Parse input arguments
    if len(args) == 1 and isinstance(args[0], tuple):
        n, m = args[0]
    else:
        n, m = args

    # Base case: sequences of length 1
    if n == 1:
        return m

    # dp[i][x] = number of sequences of length i ending with x
    # i ranges from 1 to n, x ranges from 1 to m
    dp = [ [0]*(m+1) for _ in range(n+1) ]

    # Initialization for i=1 (first element)
    for x in range(1, m+1):
        dp[1][x] = 1

    # For i from 2 to n, fill dp based on the doubling constraint
    for i in range(2, n+1):
        # To optimize, precompute prefix sums of dp[i-1]
        # But since next elements depend on dp[i-1][prev] where prev <= x/2,
        # we can iterate over x and sum dp[i-1][prev] for prev in 1..x//2
        prefix_sum = [0]*(m+1)
        for val in range(1, m+1):
            prefix_sum[val] = prefix_sum[val-1] + dp[i-1][val]

        for x in range(1, m+1):
            # previous elements must be <= x//2
            max_prev = x // 2
            if max_prev >= 1:
                dp[i][x] = prefix_sum[max_prev]
            else:
                dp[i][x] = 0

    # Total sequences of length n is sum over all ending elements
    return sum(dp[n][1:])

