def dict_depth(*args):
    if len(args) == 1:
        d = args[0]
    else:
        d = args[0]

    if not isinstance(d, dict):
        # According to specification, no validation required,
        # but if d is not dict, depth does not make sense,
        # here just treat as depth 0 (not specified)
        return 0

    if not d:
        return 1

    max_subdepth = 0
    for v in d.values():
        if isinstance(v, dict):
            subdepth = dict_depth(v)
            if subdepth > max_subdepth:
                max_subdepth = subdepth

    return 1 + max_subdepth

