def check(*args):
    # Normalize input to a string to check
    if len(args) == 1:
        arg = args[0]
        if isinstance(arg, str):
            s = arg
        elif isinstance(arg, list):
            # Join list elements to form a string
            s = ''.join(arg)
        else:
            # Convert other single argument types to string
            s = str(arg)
    else:
        # Multiple arguments: convert all to string and concatenate
        s = ''.join(str(a) for a in args)

    # Check non-empty and all characters are '0' or '1'
    return bool(s) and all(c in '01' for c in s)

