def smallest_missing(arr: list[int]) -> int:
    # Since arr is sorted, we can skip all negative numbers
    # and then check for the smallest missing non-negative integer starting from 0.

    # Find the index of the first non-negative number
    n = len(arr)
    start = 0
    while start < n and arr[start] < 0:
        start += 1

    # Now iterate from start to end
    expected = 0
    for i in range(start, n):
        if arr[i] == expected:
            expected += 1
        elif arr[i] > expected:
            # Since arr is sorted, if arr[i] > expected, expected is missing
            return expected
        # if arr[i] < expected (due to duplicates), just continue

    # If we reached here, all numbers from 0 to expected-1 are present
    return expected

