            # We assume caller wants highest_Power_of_2 of the first element.
            # If empty list/tuple, behavior not specified; assume input always valid per spec.
            n = arg[0]
        else:
            # If a single argument of unexpected type is passed, treat as int (per spec no validation)
            n = int(arg)
    else:
        # If multiple arguments, treat first argument as n
        n = args[0]

    # Compute highest power of 2 <= n
    # Since n > 0 (per spec), use bit manipulation
    # For example: for n=10 (1010b), highest power of 2 <= 10 is 8 (1000b)
    # A common way is to set only the highest set bit in n.

    # Python 3.10+ has n.bit_length() which gives number of bits needed to represent n
    # The highest power of 2 <= n is 1 << (n.bit_length() - 1)
    return 1 << (n.bit_length() - 1)

