def drop_empty(*args):
    # Handle different call signatures:
    # If called with one argument and it's a dict, use it directly.
    # If called with two arguments and they are lists (keys and values), build the dict first.
    if len(args) == 1 and isinstance(args[0], dict):
        d = args[0]
    elif len(args) == 2 and isinstance(args[0], list) and isinstance(args[1], list):
        keys, values = args
        d = dict(zip(keys, values))
    else:
        # If arguments don't match expected forms, treat as empty dict
        d = {}

    # Build and return a new dict with entries where value is not None,
    # preserving insertion order (dicts are ordered since Python 3.7).
    return {k: v for k, v in d.items() if v is not None}

