def find_remainder(arr: list[int] | tuple[int, ...], n: int) -> int:
    product_mod = 1 % n  # Handles case when n == 0 gracefully by Python raising ZeroDivisionError
    for num in arr:
        product_mod = (product_mod * (num % n)) % n
    return product_mod

