def find_Max(arr):
    left, right = 0, len(arr) - 1

    # If array is not rotated (sorted ascending), max is last element
    if arr[left] <= arr[right]:
        return arr[right]

    # Binary search for the pivot point where rotation happens
    while left < right:
        mid = (left + right) // 2

        # If mid element is greater than right element, max is in right side including mid
        if arr[mid] > arr[right]:
            left = mid + 1
        else:
            right = mid

    # left now points to the smallest element, max is element before it
    return arr[left - 1] if left > 0 else arr[-1]

