    # sum of (2^4) + (4^4) + ... + ((2*n)^4)
    # Each term is (2*i)^4 = 16 * i^4, for i in 1..n
    # sum = 16 * sum_{i=1}^n i^4

    def sum_of_fourth_powers(m):
        # formula: sum_{i=1}^m i^4 = m(m+1)(2m+1)(3m^2+3m-1)/30
        return (m * (m + 1) * (2 * m + 1) * (3 * m * m + 3 * m - 1)) // 30

    if n <= 0:
        return 0

    return 16 * sum_of_fourth_powers(n)

