def odd_length_sum(arr):
    n = len(arr)
    if n == 0:
        return 0

    total_sum = 0
    for i in range(n):
        # For each starting index i, consider odd length subarrays starting at i
        length = 1
        while i + length <= n:
            # sum the subarray arr[i:i+length]
            total_sum += sum(arr[i:i+length])
            length += 2
    return total_sum

