def check_Even_Parity(value):
    if isinstance(value, int):
        count_ones = bin(value).count('1')
    elif isinstance(value, list):
        count_ones = sum(1 for x in value if x == 1)
    else:  # assume string
        count_ones = value.count('1')
    return (count_ones % 2) == 0

