def length_Of_Last_Word(*args):
    # Accept either one argument: a string or a list of strings
    if len(args) != 1:
        return 0
    s = args[0]
    if isinstance(s, list):
        # Join list elements into a single string separated by spaces
        s = ' '.join(s)
    elif not isinstance(s, str):
        # If not string or list, return 0 as no valid input
        return 0

    # Strip trailing spaces
    s = s.rstrip()
    if not s:
        return 0

    # Find the last word by splitting from the right on spaces
    # Since trailing spaces are stripped, last word is last split element
    words = s.split(' ')
    # filter out empty strings in case of multiple spaces
    words = [w for w in words if w]
    if not words:
        return 0
    return len(words[-1])

