def lcm(*args):
    # Extract the two integers a and b from the input arguments
    if len(args) == 1:
        # Single argument: must be a tuple or list of two positive integers
        a, b = args[0]
    else:
        # Two arguments: both positive integers
        a, b = args

    # Compute gcd using Euclidean algorithm
    def gcd(x, y):
        while y:
            x, y = y, x % y
        return x

    # Compute and return LCM
    return a * b // gcd(a, b)

