def substract_elements(tuples):
    def process(element):
        # If element is a list or tuple, check if it is nested or a tuple of ints
        if isinstance(element, (list, tuple)):
            # Check if all elements are int -> then it's a tuple to subtract
            if all(isinstance(x, int) for x in element):
                # Handle empty tuple
                if len(element) == 0:
                    return 0
                # Handle single element tuple
                if len(element) == 1:
                    return element[0]
                # Subtract elements in order
                result = element[0]
                for v in element[1:]:
                    result -= v
                return result
            else:
                # Nested structure: recursively process each sub-element
                return tuple(process(e) for e in element)
        else:
            # If element is not list/tuple, it should be int in theory, just return it
            return element

    return process(tuples)

