def lucky_num(*args):
    # Normalize input to single integer n (number of lucky numbers to print)
    if len(args) == 1 and isinstance(args[0], int):
        n = args[0]
    else:
        # If input form is not as expected, fallback to default n=0 (prints nothing)
        n = 0

    # We need to generate at least n lucky numbers.
    # Since lucky numbers thin out, start with a sufficiently large list.
    # A heuristic: start with 3*n*log(n+1)+some margin (for n=0, it's 0)
    # To avoid complexity, we start with a large enough number and increase if needed.

    # Start with an initial upper bound for sieve list length
    # For small n, 2*n*10 is enough; for larger n, increase accordingly.
    # We'll try growing the list until we get enough lucky numbers.

    import math

    def generate_lucky_numbers(limit):
        # Generate lucky numbers up to index limit
        nums = list(range(1, limit + 1))
        idx = 1  # start from second element (index 1, position 2 in 1-based)
        while idx < len(nums):
            step = nums[idx]
            if step > len(nums):
                break
            # Remove every step-th element starting from index step-1 (0-based)
            # Since positions are 1-based, elements at positions step, 2*step, ...
            # correspond to indices step-1, 2*step-1, ...
            # Remove from the list all elements at these positions
            # We remove from left to right to avoid index issues
            # Best to rebuild list excluding those positions
            new_nums = []
            for i, val in enumerate(nums):
                if (i + 1) % step != 0:
                    new_nums.append(val)
            nums = new_nums
            idx += 1
        return nums

    if n <= 0:
        return

    # Start with an initial estimate for the list size
    length = max(20, int(n * 10 * math.log(n + 1)))  # heuristic

    # Increase length until we have at least n lucky numbers
    while True:
        lucky_numbers = generate_lucky_numbers(length)
        if len(lucky_numbers) >= n:
            break
        length *= 2  # double the length and try again

    # Print the first n lucky numbers separated by spaces
    print(*lucky_numbers[:n])

