def get_noOfways(*args):
    # Parse input arguments (m, n)
    if len(args) == 1:
        if isinstance(args[0], tuple):
            m, n = args[0]
        else:
            m, n = args[0], 1
    elif len(args) == 2:
        m, n = args
    else:
        # No inputs or more than 2 inputs: treat as (0,0)
        m, n = 0, 0

    # Normalize so m <= n (due to symmetry)
    m, n = sorted((m, n))

    # If the area is odd, no tilings
    if (m * n) % 2 != 0:
        return 0

    # Handle trivial cases
    if m == 0 or n == 0:
        # No cells, one way (empty tiling)
        return 1
    if m == 1:
        # 1 x n board can be tiled only if n is even, exactly 1 way
        return 1

    # For general m, n:
    # Use the known formula for the number of domino tilings of an m x n board:
    # Number of tilings = ∏_{j=1}^{m} ∏_{k=1}^{n} (4*cos^2(pi*j/(m+1)) + 4*cos^2(pi*k/(n+1)))^(1/4)
    # To avoid floating point inaccuracies, use logarithms and rounding at the end.

    import math

    def cos_sq(x):
        c = math.cos(x)
        return c * c

    total_log = 0.0
    for j in range(1, m + 1):
        cj = cos_sq(math.pi * j / (m + 1))
        for k in range(1, n + 1):
            ck = cos_sq(math.pi * k / (n + 1))
            val = 4 * cj + 4 * ck
            total_log += 0.25 * math.log(val)

    result = round(math.exp(total_log))
    return result

